  string assigned_ip = 5;
  string wireguard_config = 6;
  string message = 7;
  bool is_admin = 8;
  google.protobuf.Timestamp verified_at = 9;
}

message RegisterUserRequest {
  string email = 1;
  string wireguard_public_key = 2;
  string domain = 3;
  bool is_admin = 4;
  optional google.protobuf.Struct metadata = 5;
}

message RegisterUserResponse {
  bool success = 1;
  string user_id = 2;
  string message = 3;
  string assigned_ip = 4;
  string wireguard_config = 5;
  google.protobuf.Timestamp registered_at = 6;
}

message GetUserStatusRequest {
  string email = 1;
  string user_id = 2;
  string domain = 3;
}

message GetUserStatusResponse {
  bool registered = 1;
  string user_id = 2;
  string email = 3;
  bool email_verified = 4;
  string wireguard_public_key = 5;
  string assigned_ip = 6;
  bool is_admin = 7;
