  bool deep_check = 1;
}

message GetHealthResponse {
  bool healthy = 1;
  string status = 2;
  // Component-level status as JSON
  string components_json = 3;
  // Quota info (R11)
  int32 queries_remaining = 4;
  int32 queries_limit = 5;
  string auth_status = 6;
}

// ---------------------------------------------------------------------------
// SetupAuth (R9)
