//! The Identity Sled & Shuttle Bridge
//!
//! THE SLED: a `#[repr(C)]` struct written into `/dev/shm/plugin_schema.dat`
//! by the SchemaEngine whenever the active PluginSchema mutates.
//!
//! THE SHUTTLE: reads that mapping via zero-copy mmap, extracts the
//! Strike/Etch (hashed footprint + WireGuard identity), stamps
//! `GB_FOOTPRINT` / `GB_TRACE_ID` into the process environment, then
//! writes a stateless Xray config into `/dev/shm/xray-ghostbridge.json`
//! and spawns Xray — all without touching any Btrfs-backed path.

use memmap2::MmapOptions;
use serde::Serialize;
use std::collections::HashSet;
use std::env;
use std::fs::{self, File};
use std::io::Write;
use std::process::Command;
use std::sync::atomic::{AtomicU64, Ordering};
use zbus::{Connection, Proxy};

pub const SHM_SLED_PATH: &str = "/dev/shm/plugin_schema.dat";
pub const SHM_XRAY_CONFIG: &str = "/dev/shm/xray-ghostbridge.json";

// ── Subid taxonomy ────────────────────────────────────────────────────────────

/// Seven operational categories for the subid taxonomy.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SubidCategory {
    /// Authoritative source / ingress channel.
    Src,
    /// Source-to-object projection / mirror publication.
    Prj,
    /// Schema contract / vocabulary / control-mapping artifact.
    Sch,
    /// Write-path mutation / state change.
    Mut,
    /// Read-path observation / enumeration / discovery.
    Obs,
    /// Emitted signal / audit-chain event / proof.
    Evt,
    /// Consumer-facing rendering / materialized presentation surface.
    Exp,
}

impl SubidCategory {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Src => "src",
            Self::Prj => "prj",
            Self::Sch => "sch",
            Self::Mut => "mut",
            Self::Obs => "obs",
            Self::Evt => "evt",
            Self::Exp => "exp",
        }
    }

    pub fn parse(s: &str) -> Option<Self> {
        match s {
            "src" => Some(Self::Src),
            "prj" => Some(Self::Prj),
            "sch" => Some(Self::Sch),
            "mut" => Some(Self::Mut),
            "obs" => Some(Self::Obs),
            "evt" => Some(Self::Evt),
            "exp" => Some(Self::Exp),
            _ => None,
        }
    }
}

/// Parsed subid components.
///
/// Pattern: `<category>.<component-type>.<subject>.<verb>[.<facet>][@vN]`
/// Example:  `sch.network.plugin-schema.resolve@v1`
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SubidTaxonomy {
    pub category: SubidCategory,
    pub component_type: String,
    pub subject: String,
    pub verb: String,
    pub facet: Option<String>,
    pub version: u8,
}

impl SubidTaxonomy {
    /// Parse a subid string into its taxonomy components.
    pub fn parse(s: &str) -> Result<Self, String> {
        // Strip optional @vN suffix
        let (body, version) = if let Some(at) = s.rfind('@') {
            let ver_str = &s[at + 1..];
            let ver: u8 = ver_str
                .strip_prefix('v')
                .and_then(|n| n.parse().ok())
                .ok_or_else(|| format!("invalid version suffix: {ver_str}"))?;
            (&s[..at], ver)
        } else {
            (s, 0)
        };

        let mut parts = body.splitn(5, '.');
        let cat_str = parts.next().ok_or("missing category")?;
        let category =
            SubidCategory::parse(cat_str).ok_or_else(|| format!("unknown category: {cat_str}"))?;
        let component_type = parts.next().ok_or("missing component-type")?.to_string();
        let subject = parts.next().ok_or("missing subject")?.to_string();
        let verb = parts.next().ok_or("missing verb")?.to_string();
        let facet = parts.next().map(str::to_string);

        // Basic segment validation: lowercase ASCII + hyphens only
        for seg in [&component_type, &subject, &verb] {
            if seg.is_empty()
                || !seg
                    .chars()
                    .all(|c| c.is_ascii_lowercase() || c == '-' || c.is_ascii_digit())
            {
                return Err(format!(
                    "invalid segment '{seg}': must be lowercase ascii/digits/hyphens"
                ));
            }
        }

        Ok(Self {
            category,
            component_type,
            subject,
            verb,
            facet,
            version,
        })
    }

    /// Reconstruct the canonical subid string.
    pub fn canonical(&self) -> String {
        let mut s = format!(
            "{}.{}.{}.{}",
            self.category.as_str(),
            self.component_type,
            self.subject,
            self.verb,
        );
        if let Some(f) = &self.facet {
            s.push('.');
            s.push_str(f);
        }
        if self.version > 0 {
            s.push_str(&format!("@v{}", self.version));
        }
        s
    }
}

impl std::fmt::Display for SubidTaxonomy {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.canonical())
    }
}

/// THE SLED — 1:1 zero-copy shared memory layout.
///
/// Written by SchemaEngine (`write_sled`), read by the Shuttle via mmap.
/// Never touches disk; lives entirely in tmpfs (`/dev/shm`).
///
/// Matches `.kiro/specs/3tched-schema-shuttle-xray-pipeline` exactly.
/// Layout (152 bytes total):
///   wireguard_pubkey    [u8; 32]   offset 0
///   mutation_index      u64        offset 32
///   hashed_footprint    [u8; 32]   offset 40   (Blake3)
///   trace_id            [u8; 16]   offset 72   (UUID v4, network order)
///   schema_version      u32        offset 88
///   reserved            [u8; 60]   offset 92
#[repr(C)]
#[derive(Debug, Clone, Serialize)]
pub struct IdentitySled {
    /// Raw Curve25519 WireGuard peer key.
    pub wireguard_pubkey: [u8; 32],
    /// Monotonic schema mutation counter.
    pub mutation_index: u64,
    /// Blake3 hashed footprint of the canonicalized schema state.
    pub hashed_footprint: [u8; 32],
    /// UUID v4 trace ID (16 raw bytes, network order).
    pub trace_id: [u8; 16],
    /// Schema version for compatibility.
    pub schema_version: u32,
    /// Qdrant vector ID for the last reasoning episode (UUID v4, 16 raw bytes).
    /// Bound to identity: every vectorized episode is traceable to this sled.
    pub vector_id: [u8; 16],
    /// Reserved for future use (zero-initialized).
    #[serde(skip)]
    pub reserved: [u8; 44],
}

impl Default for IdentitySled {
    fn default() -> Self {
        Self {
            wireguard_pubkey: [0u8; 32],
            mutation_index: 0,
            hashed_footprint: [0u8; 32],
            trace_id: [0u8; 16],
            schema_version: 0,
            vector_id: [0u8; 16],
            reserved: [0u8; 44],
        }
    }
}

impl IdentitySled {
    pub const SIZE: usize = std::mem::size_of::<Self>();

    /// Hex-encode the trace_id field for header injection.
    pub fn trace_id_hex(&self) -> String {
        hex::encode(self.trace_id)
    }

    /// Hex-encode the vector_id for Qdrant upsert / lookup.
    pub fn vector_id_hex(&self) -> String {
        hex::encode(self.vector_id)
    }

    /// UUID string representation of vector_id.
    pub fn vector_id_uuid(&self) -> String {
        let b = self.vector_id;
        format!(
            "{:02x}{:02x}{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}",
            b[0],b[1],b[2],b[3],b[4],b[5],b[6],b[7],b[8],b[9],b[10],b[11],b[12],b[13],b[14],b[15]
        )
    }

    /// Absolute Base validity check per the spec:
    /// a sled is valid only if its footprint and trace_id are non-zero.
    pub fn is_sled_valid(&self) -> bool {
        self.hashed_footprint != [0u8; 32] && self.trace_id != [0u8; 16]
    }
}

// ── Zero-Btrfs disk-I/O guard ───────────────────────────────────────────────

/// Linux tmpfs magic number (`TMPFS_MAGIC`).
const TMPFS_MAGIC: libc::c_long = 0x01021994;

/// Abort if the directory backing `path` is not mounted on tmpfs.
///
/// The Shuttle must never trigger unintended Btrfs mutation loops.
/// NVMe I/O is reserved strictly for the vectorized footprint transport
/// (blockchain); all sled and Xray config writes must live in tmpfs.
fn assert_tmpfs_or_abort(path: &str) -> std::io::Result<()> {
    let parent = std::path::Path::new(path)
        .parent()
        .unwrap_or(std::path::Path::new("/"));

    let c_path = std::ffi::CString::new(parent.as_os_str().as_encoded_bytes())
        .map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidInput, e))?;

    let mut buf: libc::statfs = unsafe { std::mem::zeroed() };
    let rc = unsafe { libc::statfs(c_path.as_ptr(), &mut buf) };
    if rc != 0 {
        return Err(std::io::Error::last_os_error());
    }

    if buf.f_type as libc::c_long != TMPFS_MAGIC {
        tracing::error!(
            path = %path,
            parent = %parent.display(),
            f_type = buf.f_type,
            "ABORT: sled write would hit disk (not tmpfs). Zero-Btrfs rule violated."
        );
        return Err(std::io::Error::new(
            std::io::ErrorKind::PermissionDenied,
            format!(
                "Zero-Btrfs Overhead violation: {} is on filesystem type {}, not tmpfs",
                parent.display(),
                buf.f_type
            ),
        ));
    }

    Ok(())
}

// ── Writer side (called from SchemaEngine) ───────────────────────────────────

/// Atomically write the active sled into `/dev/shm`.
///
/// Uses a tmp-file + rename so readers never see a partial write.
/// Aborts if the target path is not on tmpfs (Zero-Btrfs Overhead rule).
pub fn write_sled(sled: &IdentitySled) -> std::io::Result<()> {
    assert_tmpfs_or_abort(SHM_SLED_PATH)?;

    let tmp = format!("{}.tmp", SHM_SLED_PATH);
    let bytes: &[u8] = unsafe {
        std::slice::from_raw_parts(sled as *const IdentitySled as *const u8, IdentitySled::SIZE)
    };
    let mut f = File::create(&tmp)?;
    f.write_all(bytes)?;
    f.sync_data()?;
    fs::rename(&tmp, SHM_SLED_PATH)?;
    Ok(())
}

// ── Reader side (the Shuttle) ────────────────────────────────────────────────

/// Read the sled from shm — zero copy, no allocation.
///
/// # Safety
/// The caller must ensure no concurrent writer is modifying the file
/// mid-read.  `write_sled` uses rename so this is safe in practice.
pub fn read_sled() -> std::io::Result<(*const IdentitySled, memmap2::Mmap)> {
    let file = File::open(SHM_SLED_PATH)?;
    let mmap = unsafe { MmapOptions::new().len(IdentitySled::SIZE).map(&file)? };
    let ptr = mmap.as_ptr() as *const IdentitySled;
    Ok((ptr, mmap))
}

// ── Unix socket endpoint ──────────────────────────────────────────────────────

/// A unix socket endpoint proxied into an xray inbound + outbound pair.
///
/// Declared via `UNIX_SOCKET_ENDPOINTS=label:path:port[,…]`, e.g.:
///   `qdrant:/run/qdrant.sock:6334`
#[derive(Debug, Clone)]
pub struct SocketEntry {
    /// Xray tag suffix (e.g. `"qdrant"`) — becomes `"to-<label>"` / `"<label>-in"`.
    pub label: String,
    /// Filesystem path of the unix domain socket.
    pub path: String,
    /// Local TCP port xray should listen on and proxy into the socket.
    pub port: u16,
}

/// Parse `UNIX_SOCKET_ENDPOINTS` env var into a list of `SocketEntry`.
///
/// Format: `label:/path/to/sock:port[,…]`
/// Example: `qdrant:/run/qdrant.sock:6334`
pub fn socket_entries_from_env() -> Vec<SocketEntry> {
    let Ok(raw) = env::var("UNIX_SOCKET_ENDPOINTS") else {
        return vec![];
    };
    raw.split(',')
        .filter_map(|entry| {
            // Split into exactly 3 parts: label, path, port
            let mut parts = entry.trim().splitn(3, ':');
            let label = parts.next()?.to_string();
            let path = parts.next()?.to_string(); // already has leading '/'
            let port: u16 = parts.next()?.trim().parse().ok()?;
            Some(SocketEntry { label, path, port })
        })
        .collect()
}

// ── Xray config generator ─────────────────────────────────────────────────────

fn write_xray_config(
    footprint: &str,
    trace_id: &str,
    nextdns_profile: &str,
    uuid: &str,
    private_key: &str,
    short_id: &str,
) -> std::io::Result<()> {
    let sockets = socket_entries_from_env();
    write_xray_config_with_sockets(
        footprint,
        trace_id,
        nextdns_profile,
        uuid,
        private_key,
        short_id,
        &sockets,
    )
}

fn write_xray_config_with_sockets(
    footprint: &str,
    trace_id: &str,
    nextdns_profile: &str,
    uuid: &str,
    private_key: &str,
    short_id: &str,
    sockets: &[SocketEntry],
) -> std::io::Result<()> {
    // Build socket inbounds: one dokodemo-door per unix socket endpoint.
    let socket_inbounds: String = sockets
        .iter()
        .map(|s| {
            format!(
                r#",
    {{
      "tag": "{label}-in",
      "port": {port},
      "listen": "127.0.0.1",
      "protocol": "dokodemo-door",
      "settings": {{ "network": "tcp", "address": "127.0.0.1", "port": {port} }}
    }}"#,
                label = s.label,
                port = s.port,
            )
        })
        .collect();

    // Build socket outbounds: freedom via xray domain-socket transport.
    let socket_outbounds: String = sockets
        .iter()
        .map(|s| {
            format!(
                r#",
    {{
      "tag": "to-{label}",
      "protocol": "freedom",
      "streamSettings": {{
        "network": "ds",
        "dsSettings": {{ "path": "{path}", "abstract": false, "padding": false }}
      }}
    }}"#,
                label = s.label,
                path = s.path,
            )
        })
        .collect();

    // Build socket routing rules: inbound tag → outbound tag.
    let socket_rules: String = sockets
        .iter()
        .map(|s| {
            format!(
                r#",
      {{ "type": "field", "inboundTag": ["{label}-in"], "outboundTag": "to-{label}" }}"#,
                label = s.label,
            )
        })
        .collect();

    let config = format!(
        r#"{{
  "log": {{ "loglevel": "warning" }},
  "dns": {{
    "servers": [ "https://dns.nextdns.io/{profile}/Ghostbridge-Incus" ],
    "tag": "nextdns-in"
  }},
  "inbounds": [
    {{
      "tag": "reality-in",
      "port": 443,
      "listen": "0.0.0.0",
      "protocol": "vless",
      "settings": {{
        "clients": [{{ "id": "{uuid}", "flow": "xtls-rprx-vision" }}],
        "decryption": "none"
      }},
      "streamSettings": {{
        "network": "tcp",
        "security": "reality",
        "realitySettings": {{
          "show": false,
          "dest": "www.microsoft.com:443",
          "serverNames": ["www.microsoft.com"],
          "privateKey": "{private_key}",
          "shortIds": ["{short_id}"]
        }}
      }}
    }},
    {{
      "tag": "ovs-socks-in",
      "port": 1080,
      "listen": "10.200.0.1",
      "protocol": "socks",
      "settings": {{ "auth": "noauth", "udp": true }}
    }},
    {{
      "tag": "ovs-tproxy-in",
      "port": 12345,
      "listen": "10.200.0.1",
      "protocol": "dokodemo-door",
      "settings": {{ "network": "tcp,udp", "followRedirect": true }},
      "streamSettings": {{ "sockopt": {{ "tproxy": "tproxy" }} }}
    }}{socket_inbounds}
  ],
  "outbounds": [
    {{
      "tag": "to-grpc-bridge",
      "protocol": "freedom",
      "settings": {{ "redirect": "127.0.0.1:18789" }},
      "streamSettings": {{
        "network": "grpc",
        "sockopt": {{ "tcpNoDelay": true, "mark": 255 }},
        "grpcSettings": {{
          "serviceName": "Ghostbridge.StateSync",
          "multiMode": true,
          "metadata": {{
            "X-Ghostbridge-Footprint": "{footprint}",
            "X-Ghostbridge-Trace-ID": "{trace_id}"
          }}
        }}
      }}
    }},
    {{
      "tag": "to-cognitive-mcp",
      "protocol": "freedom",
      "sendThrough": "10.200.0.1",
      "settings": {{ "redirect": "10.200.0.2:50052" }},
      "streamSettings": {{
        "network": "grpc",
        "sockopt": {{ "tcpNoDelay": true, "mark": 255 }},
        "grpcSettings": {{
          "serviceName": "operation.cognitive.v1.CognitiveToolService",
          "multiMode": true,
          "metadata": {{
            "X-Ghostbridge-Footprint": "{footprint}",
            "X-Ghostbridge-Trace-ID": "{trace_id}"
          }}
        }}
      }}
    }},
    {{
      "tag": "direct",
      "protocol": "freedom"
    }},
    {{ "tag": "dns-out", "protocol": "dns" }}{socket_outbounds}
  ],
  "routing": {{
    "domainStrategy": "IPIfNonMatch",
    "rules": [
      {{ "type": "field", "port": 53, "outboundTag": "dns-out" }},
      {{
        "type": "field",
        "inboundTag": ["ovs-socks-in", "ovs-tproxy-in"],
        "domain": ["full:mcp.internal"],
        "outboundTag": "to-cognitive-mcp"
      }},
      {{
        "type": "field",
        "inboundTag": ["ovs-socks-in", "ovs-tproxy-in"],
        "domain": ["full:dashboard.3tched.com", "full:grpc.internal"],
        "outboundTag": "to-grpc-bridge"
      }}{socket_rules},
      {{ "type": "field", "network": "tcp,udp", "outboundTag": "direct" }}
    ]
  }}
}}"#,
        profile = nextdns_profile,
        footprint = footprint,
        trace_id = trace_id,
        uuid = uuid,
        private_key = private_key,
        short_id = short_id,
        socket_inbounds = socket_inbounds,
        socket_outbounds = socket_outbounds,
        socket_rules = socket_rules,
    );

    let tmp = format!("{}.tmp", SHM_XRAY_CONFIG);
    let mut f = File::create(&tmp)?;
    f.write_all(config.as_bytes())?;
    f.sync_data()?;
    fs::rename(&tmp, SHM_XRAY_CONFIG)?;
    Ok(())
}

// ── WireGuard-driven sled writer ─────────────────────────────────────────────

static MUTATION_INDEX: AtomicU64 = AtomicU64::new(0);

/// Decode a base64 WireGuard public key (32-byte Curve25519) into raw bytes.
fn decode_wg_pubkey(b64: &str) -> [u8; 32] {
    use base64::Engine;
    base64::engine::general_purpose::STANDARD
        .decode(b64.trim())
        .ok()
        .and_then(|v| v.try_into().ok())
        .unwrap_or([0u8; 32])
}

/// Build and atomically write the sled from live WireGuard state.
///
/// THE STRIKE/ETCH -- single source of truth for the identity footprint.
///
/// Blake3( wg_pubkey || schema_catalog_hash(/dev/shm/live-schema.json) || mutation_index || source_port ).
/// source_port is the per-session WireGuard-observed source port (0 when none). It binds the
/// footprint to the session network context for the accountability loop -- it is NOT an auth
/// factor (WireGuard is the authenticator; see op-grpc-bridge GhostbridgeInterceptor).
pub fn etch_footprint(wireguard_pubkey: &[u8; 32], mutation_index: u64, source_port: u16) -> [u8; 32] {
    let schema_catalog_hash = std::fs::read("/dev/shm/live-schema.json")
        .map(|bytes| blake3::hash(&bytes))
        .unwrap_or_else(|_| blake3::Hash::from([0u8; 32]));

    let mut hasher = blake3::Hasher::new();
    hasher.update(wireguard_pubkey);
    hasher.update(schema_catalog_hash.as_bytes());
    hasher.update(&mutation_index.to_le_bytes());
    hasher.update(&source_port.to_le_bytes());
    hasher.finalize().into()
}

/// Per-session WireGuard source port observed for peer_pubkey, parsed from
/// wg show <iface> dump (iface from WG_INTERFACE, default wg0).
///
/// Returns 0 when the peer has no current endpoint (not connected, or a local self-write),
/// so the footprint degrades gracefully to the port-less base.
pub fn peer_source_port(peer_pubkey: &str) -> u16 {
    let iface = env::var("WG_INTERFACE").unwrap_or_else(|_| "wg0".to_string());
    let out = match Command::new("wg").arg("show").arg(&iface).arg("dump").output() {
        Ok(o) if o.status.success() => o,
        _ => return 0,
    };
    let text = String::from_utf8_lossy(&out.stdout);
    for line in text.lines() {
        // peer fields: pubkey, psk, endpoint, allowed-ips, last-hs, rx, tx, keepalive
        let fields: Vec<&str> = line.split_whitespace().collect();
        if fields.len() >= 3 && fields[0] == peer_pubkey {
            let endpoint = fields[2];
            if endpoint == "(none)" {
                return 0;
            }
            return endpoint
                .rsplit(":")
                .next()
                .and_then(|p| p.parse::<u16>().ok())
                .unwrap_or(0);
        }
    }
    0
}

/// Reads `GB_TRACE_ID` from environment to propagate an existing trace;
/// if absent, mints a fresh UUID v4.  All extra metadata (subid, compliance,
/// routing) lives in environment variables — the sled itself is the spec
/// layout and nothing more.
pub fn write_sled_from_wg(peer_pubkey: &str) -> std::io::Result<()> {
    let wireguard_pubkey = decode_wg_pubkey(peer_pubkey);
    let mutation_index = MUTATION_INDEX.fetch_add(1, Ordering::Relaxed);

    // Per-session WireGuard source port binds the footprint to the session
    // network context (accountability loop); then the canonical Strike/Etch.
    let source_port = peer_source_port(peer_pubkey);
    let hashed_footprint = etch_footprint(&wireguard_pubkey, mutation_index, source_port);

    // Trace propagation: reuse existing UUID if present, else mint v4
    let trace_id: [u8; 16] = if let Ok(existing) = env::var("GB_TRACE_ID") {
        hex::decode(existing.trim())
            .ok()
            .and_then(|v| v.try_into().ok())
            .unwrap_or_else(|| uuid::Uuid::new_v4().into_bytes())
    } else {
        uuid::Uuid::new_v4().into_bytes()
    };

    let sled = IdentitySled {
        wireguard_pubkey,
        mutation_index,
        hashed_footprint,
        trace_id,
        vector_id: [0u8; 16],
        schema_version: 1,
        reserved: [0u8; 44],
    };
    write_sled(&sled)
}

/// Write the sled with fully explicit fields — called from SchemaEngine on mutation.
///
/// `trace_id` is passed as hex; if empty a fresh UUID v4 is minted.
pub fn write_sled_full(
    peer_pubkey: &str,
    mutation_index: u64,
    trace_id_hex: &str,
) -> std::io::Result<()> {
    let wireguard_pubkey = decode_wg_pubkey(peer_pubkey);

    // Per-session WireGuard source port binds the footprint to the session
    // network context (accountability loop); then the canonical Strike/Etch.
    let source_port = peer_source_port(peer_pubkey);
    let hashed_footprint = etch_footprint(&wireguard_pubkey, mutation_index, source_port);

    let trace_id: [u8; 16] = if trace_id_hex.is_empty() {
        uuid::Uuid::new_v4().into_bytes()
    } else {
        hex::decode(trace_id_hex.trim())
            .ok()
            .and_then(|v| v.try_into().ok())
            .unwrap_or_else(|| uuid::Uuid::new_v4().into_bytes())
    };

    let sled = IdentitySled {
        wireguard_pubkey,
        mutation_index,
        hashed_footprint,
        trace_id,
        vector_id: [0u8; 16],
        schema_version: 1,
        reserved: [0u8; 44],
    };
    write_sled(&sled)
}

/// Watch for new WireGuard peers using `ip monitor` — fires instantly on handshake,
/// no polling delay. Re-writes the sled and xray config on each new peer.
/// Runs forever; call from a thread.
pub fn watch_wireguard_handshakes(iface: &str) {
    let iface = iface.to_string();

    // `ip monitor route` inside wg-xray fires the instant a WireGuard peer
    // route appears — no polling delay. wg0 lives in the container namespace.
    let mut monitor = loop {
        match Command::new("incus")
            .args(["exec", "wg-xray", "--", "ip", "monitor", "route"])
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::null())
            .spawn()
        {
            Ok(child) => break child,
            Err(e) => {
                tracing::warn!("incus exec ip monitor spawn failed: {} — retrying in 5s", e);
                std::thread::sleep(std::time::Duration::from_secs(5));
            }
        }
    };

    let stdout = monitor.stdout.take().expect("piped");
    let reader = std::io::BufReader::new(stdout);

    // Track the last pubkey we wrote the sled for — don't re-write for same peer.
    let mut last_pubkey = String::new();

    use std::io::BufRead;
    for line in reader.lines() {
        let Ok(line) = line else { break };

        // Only act on route additions — deletions fire when a peer drops,
        // which is not a reason to rewrite the sled.
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with("Deleted") || trimmed.starts_with("del") {
            continue;
        }

        // Read current peers from inside wg-xray immediately.
        let Ok(out) = Command::new("incus")
            .args(["exec", "wg-xray", "--", "wg", "show", &iface, "latest-handshakes"])
            .output()
        else {
            continue;
        };

        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(0);

        let stdout = String::from_utf8_lossy(&out.stdout);
        for line in stdout.lines() {
            let mut parts = line.split('\t');
            let (Some(pubkey), Some(ts_str)) = (parts.next(), parts.next()) else {
                continue;
            };
            let ts: u64 = ts_str.trim().parse().unwrap_or(0);
            // Only act on handshakes within the last 30 seconds (one keepalive window).
            if ts == 0 || now.saturating_sub(ts) > 30 {
                continue;
            }
            if pubkey == last_pubkey {
                continue;
            }

            tracing::info!(peer = %pubkey, "WireGuard peer → updating identity sled");
            last_pubkey = pubkey.to_string();

            if let Err(e) = write_sled_from_wg(pubkey) {
                tracing::warn!("write_sled_from_wg failed: {}", e);
                continue;
            }

            if let Ok((ptr, _mmap)) = read_sled() {
                let sled = unsafe { &*ptr };
                let footprint_hex = hex::encode(sled.hashed_footprint);
                let trace_id = sled.trace_id_hex();
                let Ok(profile) = env::var("NEXTDNS_PROFILE_ID") else { continue };
                let Ok(uuid) = env::var("XRAY_UUID") else { continue };
                let Ok(privkey) = env::var("XRAY_PRIVATE_KEY") else { continue };
                let Ok(short) = env::var("XRAY_SHORT_ID") else { continue };
                if let Err(e) = write_xray_config(&footprint_hex, &trace_id, &profile, &uuid, &privkey, &short) {
                    tracing::warn!("write_xray_config failed: {}", e);
                }
            }
        }
    }

    // ip monitor exited — respawn the thread.
    tracing::warn!("ip monitor exited — restarting watcher in 2s");
    std::thread::sleep(std::time::Duration::from_secs(2));
    watch_wireguard_handshakes(&iface);
}

// ── Public entry point ────────────────────────────────────────────────────────

/// Run the Shuttle: map the Sled, stamp env vars, write Xray config, spawn Xray.
///
/// This is the only function that should be called from the shuttle binary.
/// It intentionally avoids all SQLite, D-Bus, and Btrfs-backed paths.
pub fn run_schema_shuttle() -> Result<(), Box<dyn std::error::Error>> {
    // 1. Zero-copy read of the Absolute Base Schema
    let (ptr, _mmap) = read_sled()?;
    let sled = unsafe { &*(ptr) };

    // 2. Extract Strike/Etch — hex-encode for env injection
    let footprint_hex = hex::encode(sled.hashed_footprint);
    let trace_id = sled.trace_id_hex();
    let wg_pubkey_hex = hex::encode(sled.wireguard_pubkey);

    // 3. Stamp into environment — zero Btrfs, zero disk I/O
    env::set_var("GB_FOOTPRINT", &footprint_hex);
    env::set_var("GB_TRACE_ID", &trace_id);
    env::set_var("GB_WIREGUARD_PUBKEY", &wg_pubkey_hex);

    // 4. Write stateless Xray config — NextDNS profile from env, not sled.
    let nextdns_profile =
        env::var("NEXTDNS_PROFILE_ID").map_err(|_| "NEXTDNS_PROFILE_ID not set")?;
    let xray_uuid = env::var("XRAY_UUID").map_err(|_| "XRAY_UUID not set")?;
    let xray_privkey = env::var("XRAY_PRIVATE_KEY").map_err(|_| "XRAY_PRIVATE_KEY not set")?;
    let xray_short_id = env::var("XRAY_SHORT_ID").map_err(|_| "XRAY_SHORT_ID not set")?;
    write_xray_config(
        &footprint_hex,
        &trace_id,
        &nextdns_profile,
        &xray_uuid,
        &xray_privkey,
        &xray_short_id,
    )?;

    tracing::info!(
        footprint = %footprint_hex,
        trace_id = %trace_id,
        "Shuttle: sled read, xray config written to {}",
        SHM_XRAY_CONFIG
    );

    // 5. Start Xray via D-Bus — config lives entirely in /dev/shm
    // Per AGENTS.md §4: D-Bus first. D-Bus always. D-Bus only.
    // Use block_on since run_schema_shuttle is synchronous
    let rt = tokio::runtime::Runtime::new()?;
    match rt.block_on(start_xray_via_dbus(SHM_XRAY_CONFIG)) {
        Ok(()) => tracing::info!("Xray started via D-Bus opdbus.v1"),
        Err(e) => {
            tracing::error!(
                "Failed to start Xray via D-Bus: {}. Ensure op-xray-daemon is running.",
                e
            );
            return Err(e.into());
        }
    }

    // 6. Watch for new WireGuard handshakes and keep the sled current
    let iface = env::var("WG_INTERFACE").unwrap_or_else(|_| "wg0".to_string());
    std::thread::spawn(move || watch_wireguard_handshakes(&iface));

    Ok(())
}

/// Start Xray via D-Bus service (opdbus.v1.Xray)
///
/// Per AGENTS.md §4: All control plane operations must go through D-Bus.
/// The op-xray-daemon manages the xray process lifecycle.
async fn start_xray_via_dbus(config_path: &str) -> anyhow::Result<()> {
    let conn = Connection::system()
        .await
        .map_err(|e| anyhow::anyhow!("Failed to connect to system D-Bus: {}", e))?;

    let proxy = Proxy::new(&conn, "opdbus.v1", "/opdbus/v1/xray", "opdbus.v1.Xray")
        .await
        .map_err(|e| anyhow::anyhow!("Failed to create Xray D-Bus proxy: {}", e))?;

    let (success, message): (bool, String) = proxy
        .call_method("start", &(config_path,))
        .await
        .map_err(|e| anyhow::anyhow!("Failed to call Xray start via D-Bus: {}", e))?
        .body()
        .deserialize()
        .map_err(|e| anyhow::anyhow!("Failed to deserialize Xray response: {}", e))?;

    if success {
        Ok(())
    } else {
        Err(anyhow::anyhow!("Xray D-Bus start failed: {}", message))
    }
}

//! Xray D-Bus Daemon
//!
//! Provides D-Bus interfaces for managing the Xray proxy daemon lifecycle.
//! Replaces direct subprocess spawning with a schema-driven D-Bus service.
//!
//! D-Bus object path: /opdbus/v1/xray
//! Interface: org.opdbus.v1.Xray
//!
//! ## Architecture
//!
//! Per AGENTS.md D-Bus-first rules:
//! - All xray control operations go through D-Bus methods
//! - Config path is /dev/shm/xray_config.json per AGENTS.md §4a (Zero-Btrfs)
//! - No direct Command::new("xray") spawning - use D-Bus service instead
//!
//! ## Methods
//! - start(config_path) -> (bool, String)
//! - stop() -> (bool, String)
//! - restart(config_path) -> (bool, String)
//! - status() -> JSON string
//! - reload() -> (bool, String)
//! - get_config() -> String

use anyhow::{Context, Result};
use tokio::signal;
use tracing::info;
use zbus::connection::Connection;

mod dbus;
use dbus::XrayService;

/// CLI arguments
#[derive(Debug, Clone)]
struct Args {
    /// Initial config path to use on startup
    config_path: Option<String>,
}

impl Args {
    fn parse() -> Self {
        let args: Vec<String> = std::env::args().collect();
        let mut config_path = None;

        let mut i = 1;
        while i < args.len() {
            match args[i].as_str() {
                "--config" => {
                    if i + 1 < args.len() {
                        config_path = Some(args[i + 1].clone());
                        i += 2;
                    } else {
                        eprintln!("Error: --config requires an argument");
                        std::process::exit(1);
                    }
                }
                "-h" | "--help" => {
                    println!("Xray D-Bus Daemon - org.opdbus.v1.Xray");
                    println!();
                    println!("Usage: op-xray-daemon [OPTIONS]");
                    println!();
                    println!("Options:");
                    println!("  --config <path>    Initial config path (default: /dev/shm/xray_config.json)");
                    println!("  -h, --help         Show this help message");
                    std::process::exit(0);
                }
                _ => {
                    eprintln!("Warning: Unknown argument: {}", args[i]);
                    i += 1;
                }
            }
        }

        Self { config_path }
    }
}

/// Default config path per AGENTS.md §4a (Zero-Btrfs)
const DEFAULT_CONFIG_PATH: &str = "/dev/shm/xray_config.json";

#[tokio::main]
async fn main() -> Result<()> {
    // Initialize logging with env filter
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    info!("Starting op-xray-daemon");

    // Parse CLI arguments
    let args = Args::parse();

    // Determine config path
    let config_path = args
        .config_path
        .unwrap_or_else(|| DEFAULT_CONFIG_PATH.to_string());
    info!("Using config path: {}", config_path);

    // Create D-Bus service
    let service = XrayService::new();

    // Build D-Bus connection
    let conn = Connection::system()
        .await
        .context("Failed to connect to system D-Bus")?;

    info!("Connected to system D-Bus");

    // Serve the XrayService on the connection
    conn.object_server()
        .at("/opdbus/v1/xray", service)
        .await
        .context("Failed to register D-Bus object")?;

    // Request the bus name
    conn.request_name("opdbus.v1")
        .await
        .context("Failed to request bus name")?;

    info!("D-Bus service registered at /opdbus/v1/xray");
    info!("Interface: org.opdbus.v1.Xray");

    // Set up signal handlers for graceful shutdown
    let mut sigterm = signal::unix::signal(signal::unix::SignalKind::terminate())
        .context("Failed to register SIGTERM handler")?;
    let mut sigint = signal::unix::signal(signal::unix::SignalKind::interrupt())
        .context("Failed to register SIGINT handler")?;

    info!("Daemon ready - waiting for requests");

    // If config was provided via CLI, auto-start xray
    if std::path::Path::new(&config_path).exists() {
        info!("Auto-starting xray with config: {}", config_path);
        // This would require access to the service instance, which is managed by zbus
        // For now, clients must call Start() explicitly via D-Bus
        info!("Note: Auto-start not implemented - use D-Bus Start() method");
    }

    // Wait for shutdown signal
    tokio::select! {
        _ = sigterm.recv() => {
            info!("Received SIGTERM, shutting down gracefully...");
        }
        _ = sigint.recv() => {
            info!("Received SIGINT, shutting down gracefully...");
        }
    }

    info!("op-xray-daemon shutting down");
    Ok(())
}

//! D-Bus service implementation for Xray daemon management
//!
//! Provides the `org.opdbus.v1.Xray` interface for controlling
//! xray process lifecycle via D-Bus.

use serde::{Deserialize, Serialize};
use std::sync::Arc;
use tokio::process::{Child as TokioChild, Command};
use tokio::sync::Mutex;
use tracing::{debug, error, info, warn};
use zbus::interface;

/// Status information for the Xray daemon
#[derive(Debug, Clone, Serialize, Deserialize)]
struct XrayStatus {
    running: bool,
    pid: Option<u32>,
    config_path: Option<String>,
    uptime_secs: Option<u64>,
    start_time: Option<String>,
}

impl XrayStatus {}

/// State container for the xray process
pub struct XrayProcessState {
    child: Option<TokioChild>,
    config_path: Option<String>,
    start_time: Option<std::time::Instant>,
}

impl XrayProcessState {
    fn new() -> Self {
        Self {
            child: None,
            config_path: None,
            start_time: None,
        }
    }

    fn is_running(&self) -> bool {
        // Check if child exists. For TokioChild, we can use try_wait via a ref
        // but we need mutable access. Instead, we track state separately.
        // For now, just check if child handle exists (we update on operations).
        self.child.is_some()
    }

    fn get_pid(&self) -> Option<u32> {
        // child.id() returns Option<u32>
        self.child.as_ref().and_then(|c| c.id())
    }

    fn get_uptime_secs(&self) -> Option<u64> {
        self.start_time.map(|t| t.elapsed().as_secs())
    }

    fn get_start_time(&self) -> Option<String> {
        // Use current time minus elapsed to get start time
        self.start_time.and_then(|t| {
            let elapsed = t.elapsed();
            let now = chrono::Local::now();
            let start = now - chrono::Duration::from_std(elapsed).ok()?;
            Some(start.format("%Y-%m-%dT%H:%M:%S").to_string())
        })
    }
}

/// D-Bus service for managing Xray daemon lifecycle
pub struct XrayService {
    state: Arc<Mutex<XrayProcessState>>,
}

impl XrayService {
    pub fn new() -> Self {
        Self {
            state: Arc::new(Mutex::new(XrayProcessState::new())),
        }
    }

    /// Create a status snapshot for external reporting
    async fn get_status_snapshot(&self) -> XrayStatus {
        let state = self.state.lock().await;
        XrayStatus {
            running: state.is_running(),
            pid: state.get_pid(),
            config_path: state.config_path.clone(),
            uptime_secs: state.get_uptime_secs(),
            start_time: state.get_start_time(),
        }
    }
}

/// D-Bus interface implementation for org.opdbus.v1.Xray
#[interface(name = "opdbus.v1.Xray")]
impl XrayService {
    /// Start xray with the specified config path
    /// Returns (success, message)
    async fn start(&mut self, config_path: &str) -> (bool, String) {
        info!("Xray start requested with config: {}", config_path);

        let mut state = self.state.lock().await;

        // Check if already running
        if state.is_running() {
            warn!("Xray is already running, PID: {:?}", state.get_pid());
            return (
                false,
                format!("Xray is already running (PID: {:?})", state.get_pid()),
            );
        }

        // Validate config path exists
        if !std::path::Path::new(config_path).exists() {
            error!("Config file does not exist: {}", config_path);
            return (
                false,
                format!("Config file does not exist: {}", config_path),
            );
        }

        // Ensure config is in /dev/shm as per AGENTS.md §4a (Zero-Btrfs)
        if !config_path.starts_with("/dev/shm") {
            warn!(
                "Config path is not in /dev/shm, proceeding anyway: {}",
                config_path
            );
        }

        // Spawn xray process
        match Command::new("xray")
            .arg("-c")
            .arg(config_path)
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
        {
            Ok(child) => {
                let pid = child.id();
                state.child = Some(child);
                state.config_path = Some(config_path.to_string());
                state.start_time = Some(std::time::Instant::now());

                match pid {
                    Some(p) => {
                        info!("Xray started successfully, PID: {}", p);
                        (true, format!("Xray started successfully (PID: {})", p))
                    }
                    None => {
                        info!("Xray started successfully (PID unavailable)");
                        (true, "Xray started successfully".to_string())
                    }
                }
            }
            Err(e) => {
                error!("Failed to start xray: {}", e);
                (false, format!("Failed to start xray: {}", e))
            }
        }
    }

    /// Stop the running xray process
    /// Returns (success, message)
    async fn stop(&mut self) -> (bool, String) {
        info!("Xray stop requested");

        let mut state = self.state.lock().await;

        if !state.is_running() {
            warn!("Xray is not running");
            return (false, "Xray is not running".to_string());
        }

        if let Some(mut child) = state.child.take() {
            match child.kill().await {
                Ok(_) => {
                    info!("Xray process terminated");
                    state.config_path = None;
                    state.start_time = None;
                    (true, "Xray stopped successfully".to_string())
                }
                Err(e) => {
                    error!("Failed to kill xray process: {}", e);
                    // Put it back if kill failed
                    state.child = Some(child);
                    (false, format!("Failed to stop xray: {}", e))
                }
            }
        } else {
            (false, "Xray process handle not available".to_string())
        }
    }

    /// Restart xray with the specified config path
    /// Returns (success, message)
    async fn restart(&mut self, config_path: &str) -> (bool, String) {
        info!("Xray restart requested");

        // Stop first
        let stop_result = self.stop().await;
        if !stop_result.0 && !stop_result.1.contains("not running") {
            return (
                false,
                format!("Failed to stop existing xray: {}", stop_result.1),
            );
        }

        // Small delay to ensure process cleanup
        tokio::time::sleep(tokio::time::Duration::from_millis(100)).await;

        // Then start
        self.start(config_path).await
    }

    /// Get current xray status as JSON string
    async fn status(&self) -> String {
        let status = self.get_status_snapshot().await;
        match serde_json::to_string(&status) {
            Ok(json) => {
                debug!("Xray status: {}", json);
                json
            }
            Err(e) => {
                error!("Failed to serialize status: {}", e);
                r#"{"running":false,"error":"serialization failed"}"#.to_string()
            }
        }
    }

    /// Reload xray configuration by sending SIGHUP
    /// Returns (success, message)
    async fn reload(&self) -> (bool, String) {
        info!("Xray reload requested");

        let state = self.state.lock().await;

        if !state.is_running() {
            warn!("Cannot reload: Xray is not running");
            return (false, "Xray is not running".to_string());
        }

        let pid = match state.get_pid() {
            Some(p) => p,
            None => {
                return (false, "Cannot determine xray PID".to_string());
            }
        };

        // Send SIGHUP signal
        match nix::sys::signal::kill(
            nix::unistd::Pid::from_raw(pid as i32),
            nix::sys::signal::Signal::SIGHUP,
        ) {
            Ok(_) => {
                info!("Sent SIGHUP to xray PID {}", pid);
                (true, format!("Reload signal sent to xray (PID: {})", pid))
            }
            Err(e) => {
                error!("Failed to send SIGHUP to xray PID {}: {}", pid, e);
                (false, format!("Failed to send reload signal: {}", e))
            }
        }
    }

    /// Get current config path
    async fn get_config(&self) -> String {
        let state = self.state.lock().await;
        state.config_path.clone().unwrap_or_default()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_xray_status_serialization() {
        let status = XrayStatus {
            running: true,
            pid: Some(1234),
            config_path: Some("/dev/shm/xray_config.json".to_string()),
            uptime_secs: Some(3600),
            start_time: Some("2024-01-01T00:00:00".to_string()),
        };

        let json = serde_json::to_string(&status).unwrap();
        assert!(json.contains("\"running\":true"));
        assert!(json.contains("\"pid\":1234"));
        assert!(json.contains("\"config_path\":\"/dev/shm/xray_config.json\""));
    }

    #[tokio::test]
    async fn test_xray_service_creation() {
        let service = XrayService::new();
        let status = service.get_status_snapshot().await;
        assert!(!status.running);
        assert_eq!(status.pid, None);
    }
}

//! Cognitive MCP Server — Dual Transport (HTTP/SSE + gRPC)
//!
//! Single persistent backend (CozoDB) hosts every relation:
//! memory namespaces/entries, users, sessions, compliance graph, subid registry, audit log.

use crate::code_tools::register_code_tools;
use crate::cognitive_tools::CognitiveToolRegistry;
use crate::context_awareness::{ContextAwarenessConfig, ContextAwarenessEngine};
use crate::cozo_shuttle::CozoGraphShuttle;
use crate::gemini_fallback::GeminiFallback;
use crate::grpc_service::CognitiveGrpcService;
use crate::memory_store::CognitiveMemoryStore;
use crate::proto::cognitive_tool_service_server::CognitiveToolServiceServer;
use crate::qdrant_shuttle::QdrantSemanticShuttle;
use crate::quota::QuotaManager;
use crate::rag_pipeline::{RagPipeline, DEFAULT_COLLECTION};
use crate::session::SessionManager;
use crate::typed_tools;
use op_mcp::tool_registry::{RegistryExecutor, ToolRegistry};
use std::path::PathBuf;
use std::sync::Arc;

pub struct CognitiveMcpServer {
    memory_store: Arc<CognitiveMemoryStore>,
    cozo_shuttle: Arc<CozoGraphShuttle>,
    qdrant_shuttle: Option<Arc<QdrantSemanticShuttle>>,
    tool_registry: Arc<ToolRegistry>,
    session_manager: Arc<SessionManager>,
    quota_manager: Arc<QuotaManager>,
    gemini_fallback: Arc<GeminiFallback>,
    /// Code-RAG pipeline (Voyage + Qdrant). `None` when no Voyage key is found.
    rag_pipeline: Option<Arc<RagPipeline>>,
    /// Proactive coding-context awareness engine.
    context_engine: Arc<ContextAwarenessEngine>,
}

impl CognitiveMcpServer {
    /// `db_path` is the CozoDB directory backing every persistent relation
    /// (memory namespaces/entries, users, sessions, compliance graph, audit log).
    pub async fn new(db_path: &str) -> Result<Self, Box<dyn std::error::Error>> {
        let cozo_shuttle = Arc::new(CozoGraphShuttle::new_persistent(PathBuf::from(db_path))?);
        let memory_store = Arc::new(CognitiveMemoryStore::new(cozo_shuttle.clone()).await?);

        let tool_registry = Arc::new(ToolRegistry::new());

        let qdrant_shuttle = match QdrantSemanticShuttle::new().await {
            Ok(shuttle) => Some(Arc::new(shuttle)),
            Err(e) => {
                tracing::warn!(
                    error = %e,
                    "Qdrant Semantic Shuttle unavailable; cognitive MCP will continue without vector retrieval"
                );
                None
            }
        };

        let session_manager = Arc::new(SessionManager::with_defaults());
        let quota_manager = Arc::new(QuotaManager::with_defaults());
        let gemini_fallback = Arc::new(GeminiFallback::new());

        CognitiveToolRegistry::register_all(&tool_registry, memory_store.clone()).await?;

        typed_tools::register_typed_tools(
            &tool_registry,
            memory_store.clone(),
            session_manager.clone(),
            quota_manager.clone(),
        )
        .await?;

        // Code-RAG pipeline: optional, like qdrant_shuttle. Without a Voyage key
        // (env or ~/.ssh/mongo-voyage) the cognitive MCP still serves memory tools.
        let rag_pipeline = match RagPipeline::from_env() {
            Ok(p) => Some(Arc::new(p)),
            Err(e) => {
                tracing::warn!(
                    error = %e,
                    "RAG pipeline unavailable; code-context tools will not be registered"
                );
                None
            }
        };

        // Context-awareness engine drives session signals and proactive pushes.
        let context_engine = Arc::new(ContextAwarenessEngine::new(
            ContextAwarenessConfig::default(),
            memory_store.clone(),
            rag_pipeline.clone(),
        ));
        context_engine.clone().start_monitoring();

        if let Some(rag) = &rag_pipeline {
            let n = register_code_tools(
                &tool_registry,
                rag.clone(),
                context_engine.clone(),
                DEFAULT_COLLECTION.to_string(),
            )
            .await?;
            tracing::info!(registered = n, "Registered code-context tools");
        }

        Ok(Self {
            memory_store,
            cozo_shuttle,
            qdrant_shuttle,
            tool_registry,
            session_manager,
            quota_manager,
            gemini_fallback,
            rag_pipeline,
            context_engine,
        })
    }

    pub async fn start_http_server(self, addr: &str) -> Result<(), Box<dyn std::error::Error>> {
        use crate::context_server::build_context_router;
        use op_mcp::{HttpSseTransport, McpServer, McpServerConfig, Transport};

        let config = McpServerConfig {
            name: Some("cognitive-mcp".to_string()),
            compact_mode: false,
            ..Default::default()
        };

        let executor = Arc::new(RegistryExecutor::new(self.tool_registry.clone()));
        let mcp_server = Arc::new(McpServer::with_executor(config, executor));

        let mut transport = HttpSseTransport::new(addr.to_string());
        if std::env::var("COGNITIVE_MCP_CONTEXT_HTTP_DISABLED").as_deref() != Ok("1") {
            // Mount the context-awareness SSE endpoints on the same HTTP server
            // so they share auth, CORS, and the port with the MCP protocol routes.
            let context_router = build_context_router(
                self.context_engine.clone(),
                self.memory_store.clone(),
                self.session_manager.clone(),
            );
            transport = transport.with_extra_router(context_router);
        }

        tracing::info!(
            addr = %addr,
            "Cognitive MCP Server listening (MCP + context-awareness endpoints)"
        );
        transport.serve(mcp_server).await?;
        Ok(())
    }

    pub async fn start_grpc_server(&self, addr: &str) -> Result<(), Box<dyn std::error::Error>> {
        let grpc_service = CognitiveGrpcService::new(
            self.memory_store.clone(),
            self.session_manager.clone(),
            self.quota_manager.clone(),
            self.gemini_fallback.clone(),
        );

        let reflection = tonic_reflection::server::Builder::configure()
            .register_encoded_file_descriptor_set(crate::proto::FILE_DESCRIPTOR_SET)
            .build_v1()
            .expect("failed to build cognitive reflection service");

        let (mut health_reporter, health_service) = tonic_health::server::health_reporter();
        health_reporter
            .set_serving::<CognitiveToolServiceServer<CognitiveGrpcService>>()
            .await;

        let socket_addr: std::net::SocketAddr = addr.parse()?;
        tracing::info!(addr = %socket_addr, "Cognitive gRPC Server listening");

        tonic::transport::Server::builder()
            .accept_http1(true)
            .add_service(tonic_web::enable(
                CognitiveToolServiceServer::with_interceptor(
                    grpc_service,
                    crate::interceptor::ghostbridge_interceptor,
                ),
            ))
            .add_service(tonic_web::enable(reflection))
            .add_service(tonic_web::enable(health_service))
            .serve(socket_addr)
            .await?;

        Ok(())
    }

    pub async fn start_dual(
        self,
        http_addr: &str,
        grpc_addr: &str,
    ) -> Result<(), Box<dyn std::error::Error>> {
        let grpc_addr = grpc_addr.to_string();
        let http_addr = http_addr.to_string();

        let grpc_memory = self.memory_store.clone();
        let grpc_session = self.session_manager.clone();
        let grpc_quota = self.quota_manager.clone();
        let grpc_gemini = self.gemini_fallback.clone();

        let grpc_handle = tokio::spawn(async move {
            let grpc_service =
                CognitiveGrpcService::new(grpc_memory, grpc_session, grpc_quota, grpc_gemini);

            let reflection = tonic_reflection::server::Builder::configure()
                .register_encoded_file_descriptor_set(crate::proto::FILE_DESCRIPTOR_SET)
                .build_v1()
                .expect("failed to build cognitive reflection service");

            let (mut health_reporter, health_service) = tonic_health::server::health_reporter();
            health_reporter
                .set_serving::<CognitiveToolServiceServer<CognitiveGrpcService>>()
                .await;

            let socket_addr: std::net::SocketAddr = grpc_addr.parse().expect("invalid gRPC addr");
            tracing::info!(addr = %socket_addr, "Cognitive gRPC Server listening");

            tonic::transport::Server::builder()
                .accept_http1(true)
                .add_service(tonic_web::enable(
                    CognitiveToolServiceServer::with_interceptor(
                        grpc_service,
                        crate::interceptor::ghostbridge_interceptor,
                    ),
                ))
                .add_service(tonic_web::enable(reflection))
                .add_service(tonic_web::enable(health_service))
                .serve(socket_addr)
                .await
                .expect("gRPC server failed");
        });

        self.start_http_server(&http_addr).await?;
        grpc_handle.await?;
        Ok(())
    }

    pub fn memory_store(&self) -> Arc<CognitiveMemoryStore> {
        self.memory_store.clone()
    }

    pub fn cozo_shuttle(&self) -> Arc<CozoGraphShuttle> {
        self.cozo_shuttle.clone()
    }

    pub fn tool_registry(&self) -> Arc<ToolRegistry> {
        self.tool_registry.clone()
    }

    /// Register on the session D-Bus and serve until the connection drops.
    /// Runs in the background — call this before start_http_server / start_dual.
    pub async fn start_dbus(&self) -> Result<zbus::Connection, Box<dyn std::error::Error>> {
        use crate::dbus_interface::CognitiveMcpInterface;

        let conn = zbus::Connection::system().await?;
        conn.request_name("org.opdbus.CognitiveMcp").await?;

        let iface = CognitiveMcpInterface::new(self.tool_registry.clone());
        conn.object_server()
            .at("/org/opdbus/v1/cognitive", iface)
            .await?;

        tracing::info!("Cognitive MCP D-Bus interface registered at /org/opdbus/v1/cognitive");
        Ok(conn)
    }

    pub fn qdrant_shuttle(&self) -> Option<Arc<QdrantSemanticShuttle>> {
        self.qdrant_shuttle.clone()
    }

    pub fn session_manager(&self) -> Arc<SessionManager> {
        self.session_manager.clone()
    }

    pub fn quota_manager(&self) -> Arc<QuotaManager> {
        self.quota_manager.clone()
    }

    pub fn rag_pipeline(&self) -> Option<Arc<RagPipeline>> {
        self.rag_pipeline.clone()
    }

    pub fn context_engine(&self) -> Arc<ContextAwarenessEngine> {
        self.context_engine.clone()
    }
}

//! RAG ingestion pipeline for repomix content.
//!
//! Pipeline: zip → repomix parse → enrich → chunk → Voyage embed → Qdrant upsert
//!
//! Each Qdrant point payload carries rich metadata for hover display:
//!   repo, file_path, language, symbols, doc_comments, imports, tags,
//!   is_test, line_start, line_end, chunk_index, total_chunks, content_hash

use anyhow::{Context, Result};
use qdrant_client::{
    qdrant::{
        vectors_config::Config as VectorsConfigEnum, Condition, CreateCollectionBuilder, Distance,
        Filter, PointStruct, ScoredPoint, SearchPointsBuilder, UpsertPointsBuilder,
        VectorParamsBuilder, VectorsConfig,
    },
    Payload, Qdrant, QdrantError,
};
use regex::Regex;
use reqwest::Client;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::{
    collections::HashMap,
    io::{BufRead, BufReader},
    path::Path,
    sync::OnceLock,
    time::Duration,
};
use tracing::{info, warn};

// ─── constants ───────────────────────────────────────────────────────────────

pub const DEFAULT_COLLECTION: &str = "repomix_rag";
const VECTOR_DIM: u64 = 1024; // voyage-4 default
const CHUNK_LINES: usize = 80; // ~2 kB of code per chunk
const OVERLAP_LINES: usize = 12;
const VOYAGE_PUBLIC_URL: &str = "https://api.voyageai.com/v1/embeddings";
const VOYAGE_MONGODB_URL: &str = "https://ai.mongodb.com/v1/embeddings";
const VOYAGE_BATCH: usize = 32; // points per upsert batch
const VOYAGE_RATE_DELAY_MS: u64 = 120; // ms between Voyage calls

// ─── extracted file metadata ──────────────────────────────────────────────────

#[derive(Debug, Clone, Default)]
pub struct FileMeta {
    pub language: &'static str,
    pub file_type: FileType,
    pub symbols: Vec<String>, // top-level pub items
    pub doc_comments: Vec<String>,
    pub imports: Vec<String>, // use / import / require
    pub tags: Vec<String>,    // semantic auto-tags
    pub is_test: bool,
}

#[derive(Debug, Clone, Default, PartialEq)]
pub enum FileType {
    #[default]
    Source,
    Test,
