}

// ─── public API ───────────────────────────────────────────────────────────────

/// RAG query result returned by `RagPipeline::query`.
#[derive(Debug, Clone, Serialize)]
pub struct RagResult {
    pub score: f32,
    pub repo: String,
    pub file_path: String,
    pub language: String,
    pub file_type: String,
    pub symbols: Vec<String>,
    pub doc_comments: Vec<String>,
    pub imports: Vec<String>,
    pub tags: Vec<String>,
    pub is_test: bool,
    pub line_start: i64,
    pub line_end: i64,
    pub chunk_index: i64,
    pub total_chunks: i64,
    pub content: String,
}

/// Structured filters for code-aware semantic retrieval.
///
/// `repo`/`language`/`file_type` are pushed into Qdrant as server-side `must`
/// conditions. `path_contains`/`symbol_contains`/`exclude_tests` are applied
/// client-side after scoring, because they are substring/boolean predicates
/// over payload fields rather than exact keyword matches.
#[derive(Debug, Clone, Default)]
pub struct CodeFilter {
    pub repo: Option<String>,
    pub language: Option<String>,
    pub file_type: Option<String>,
    pub path_contains: Option<String>,
    pub symbol_contains: Option<String>,
    pub exclude_tests: bool,
}

impl CodeFilter {
    fn qdrant_filter(&self) -> Option<Filter> {
        let mut conds: Vec<Condition> = Vec::new();
        if let Some(repo) = &self.repo {
            conds.push(Condition::matches("repo", repo.clone()));
        }
        if let Some(lang) = &self.language {
            conds.push(Condition::matches("language", lang.clone()));
        }
        if let Some(ft) = &self.file_type {
            conds.push(Condition::matches("file_type", ft.clone()));
        }
        if conds.is_empty() {
            None
        } else {
            Some(Filter::must(conds))
        }
    }

    fn post_matches(&self, r: &RagResult) -> bool {
        if self.exclude_tests && r.is_test {
            return false;
        }
        if let Some(p) = &self.path_contains {
            if !r.file_path.to_lowercase().contains(&p.to_lowercase()) {
                return false;
            }
        }
        if let Some(s) = &self.symbol_contains {
            let needle = s.to_lowercase();
            let hit = r
                .symbols
                .iter()
                .any(|sym| sym.to_lowercase().contains(&needle))
                || r.file_path.to_lowercase().contains(&needle);
            if !hit {
                return false;
            }
        }
        true
    }
}

pub struct RagPipeline {
    qdrant: Qdrant,
    voyage_key: String,
    voyage_model: String,
    http: Client,
}

impl RagPipeline {
    pub fn from_env() -> Result<Self> {
        let voyage_key = std::env::var("VOYAGE_API_KEY")
            .or_else(|_| std::env::var("COGNITIVE_MCP_VOYAGE_API_KEY"))
            .ok()
            .or_else(voyage_key_from_file)
            .context(
                "Voyage API key not found: set VOYAGE_API_KEY, \
                 or place the key in ~/.ssh/mongo-voyage \
                 (override path with COGNITIVE_MCP_VOYAGE_KEY_FILE)",
            )?;
        // Default: voyage-4 (balanced quality/cost in the 4-series).
        // Override with COGNITIVE_MCP_VOYAGE_MODEL env var.
        //
        // Model selection guide (all 4-series are cross-compatible):
        //   • voyage-4-lite        – lowest cost, good general quality
        //   • voyage-4             – balanced cost/quality (DEFAULT)
        //   • voyage-4-large       – highest quality, highest cost
        //   • voyage-code-3        – best for code retrieval, premium price
        //
        // Because 4-series embeddings are cross-compatible, you can index
        // with voyage-4 and later query with voyage-code-3 (or vice versa)
        // without rebuilding the Qdrant collection.
        let voyage_model = std::env::var("COGNITIVE_MCP_VOYAGE_MODEL")
            .or_else(|_| std::env::var("VOYAGE_MODEL"))
            .unwrap_or_else(|_| "voyage-4".into());

        let qdrant = qdrant_client_from_env()?;

        Ok(Self {
            qdrant,
            voyage_key,
            voyage_model,
            http: Client::new(),
        })
    }

    /// Ingest a single repomix file from the zip into Qdrant.
    #[tracing::instrument(skip(self, zip_path), fields(entry_name, collection))]
    pub async fn ingest_repomix_entry(
        &self,
        zip_path: &Path,
        entry_name: &str,
        collection: &str,
    ) -> Result<IngestStats> {
        self.ensure_collection(collection).await?;

        let repo = repo_name_from_entry(entry_name);
        info!(repo = %repo, entry = %entry_name, "Ingesting repomix entry");

        let file = std::fs::File::open(zip_path)?;
        let mut archive = zip::ZipArchive::new(file)?;

        let entry_idx = (0..archive.len())
            .find(|&i| {
                archive
                    .by_index(i)
                    .map(|e| e.name().to_string())
                    .ok()
                    .as_deref()
                    == Some(entry_name)
            })
            .with_context(|| format!("Entry '{entry_name}' not found in zip"))?;

        let entry = archive.by_index(entry_idx)?;
        let reader = BufReader::new(entry);

        let mut stats = IngestStats::default();
        let mut batch: Vec<PointStruct> = Vec::new();

        for chunk in parse_and_chunk(reader, &repo) {
            stats.files_parsed += 1;
            let total = chunk.total_chunks;
            stats.chunks_created += total;

            // Embed
            let vector = match self.embed_document(&chunk.embed_text).await {
                Ok(v) => v,
                Err(e) => {
                    warn!(file = %chunk.file_path, error = %e, "Embed failed, skipping chunk");
                    stats.errors += 1;
                    continue;
                }
            };

            // Build Qdrant payload with all metadata for hover display
            let payload: Payload = serde_json::json!({
                "repo":          chunk.repo,
                "file_path":     chunk.file_path,
                "language":      chunk.meta.language,
                "file_type":     chunk.meta.file_type.as_str(),
                "symbols":       chunk.meta.symbols,
                "doc_comments":  chunk.meta.doc_comments,
                "imports":       chunk.meta.imports,
                "tags":          chunk.meta.tags,
                "is_test":       chunk.meta.is_test,
                "line_start":    chunk.line_start,
                "line_end":      chunk.line_end,
                "chunk_index":   chunk.chunk_index,
                "total_chunks":  chunk.total_chunks,
                "content":       chunk.content,
                "content_hash":  chunk.content_hash,
            })
            .try_into()
            .context("Failed to build payload")?;

            // Use content hash as stable point ID (dedup)
            batch.push(PointStruct::new(
                stable_uuid(&chunk.content_hash),
                vector,
                payload,
            ));

            if batch.len() >= VOYAGE_BATCH {
                self.flush_batch(collection, &mut batch, &mut stats).await;
                tokio::time::sleep(Duration::from_millis(VOYAGE_RATE_DELAY_MS)).await;
            }
        }

        if !batch.is_empty() {
            self.flush_batch(collection, &mut batch, &mut stats).await;
        }

        info!(
            repo = %repo,
            files = stats.files_parsed,
            chunks = stats.chunks_created,
            upserted = stats.chunks_upserted,
            "Ingest complete"
        );

        Ok(stats)
    }

    /// Semantic search over a Qdrant collection.
    #[tracing::instrument(skip(self), fields(collection, query_text, limit))]
    pub async fn query(
        &self,
        collection: &str,
        query_text: &str,
        limit: u64,
        repo_filter: Option<&str>,
    ) -> Result<Vec<RagResult>> {
        self.ensure_collection(collection).await?;

        let vector = self.embed_query(query_text).await?;

        let mut builder = SearchPointsBuilder::new(collection, vector, limit).with_payload(true);

        if let Some(repo) = repo_filter {
            builder = builder.filter(Filter::must([Condition::matches("repo", repo.to_string())]));
        }

        let response = self.qdrant.search_points(builder).await?;

        Ok(response.result.into_iter().map(point_to_result).collect())
    }

    /// Code-aware semantic search with structured filters.
    ///
    /// Server-side filters (`repo`, `language`, `file_type`) are pushed into
    /// Qdrant; path/symbol/test filters are applied client-side after scoring.
    /// subid: `obs.service.code-rag.search@v1`
    #[tracing::instrument(skip(self, filter), fields(collection, query_text, limit))]
    pub async fn query_filtered(
        &self,
        collection: &str,
        query_text: &str,
        limit: u64,
        filter: &CodeFilter,
    ) -> Result<Vec<RagResult>> {
        self.ensure_collection(collection).await?;

        let vector = self.embed_query(query_text).await?;
        let fetch = limit.saturating_mul(3).max(limit);

        let mut builder = SearchPointsBuilder::new(collection, vector, fetch).with_payload(true);
        if let Some(f) = filter.qdrant_filter() {
            builder = builder.filter(f);
        }

        let response = self.qdrant.search_points(builder).await?;
        let mut results: Vec<RagResult> = response
            .result
            .into_iter()
            .map(point_to_result)
            .filter(|r| filter.post_matches(r))
            .collect();
        results.truncate(limit as usize);
        Ok(results)
    }

    /// Fused code retrieval: semantic score + lexical/symbol boost, then
    /// deduplicated to the single best-scoring chunk per file.
    ///
    /// This is the primary retrieval surface for the `code_context` tool: it
    /// avoids returning many chunks of the same file and surfaces files whose
    /// symbols or paths lexically match the query terms.
    /// subid: `obs.service.code-rag.fused-search@v1`
    #[tracing::instrument(skip(self, filter), fields(collection, query_text, limit))]
    pub async fn query_fused(
        &self,
        collection: &str,
        query_text: &str,
        limit: u64,
        filter: &CodeFilter,
    ) -> Result<Vec<RagResult>> {
        self.ensure_collection(collection).await?;

        let vector = self.embed_query(query_text).await?;
        let fetch = limit.saturating_mul(4).clamp(limit, 64);

        let mut builder = SearchPointsBuilder::new(collection, vector, fetch).with_payload(true);
        if let Some(f) = filter.qdrant_filter() {
            builder = builder.filter(f);
        }

        let response = self.qdrant.search_points(builder).await?;

        let terms: Vec<String> = query_text
            .to_lowercase()
            .split(|c: char| !c.is_alphanumeric())
            .filter(|t| t.len() > 2)
            .map(String::from)
            .collect();

        let mut best: HashMap<String, RagResult> = HashMap::new();
        for pt in response.result {
            let mut r = point_to_result(pt);
            if !filter.post_matches(&r) {
                continue;
            }

            // Lexical/symbol boost on top of the cosine score.
            let mut boost = 0.0f32;
            let sym = r.symbols.join(" ").to_lowercase();
            let path = r.file_path.to_lowercase();
            for t in &terms {
                if sym.contains(t) {
                    boost += 0.05;
                }
                if path.contains(t) {
                    boost += 0.03;
                }
            }
            r.score += boost.min(0.25);

            best.entry(r.file_path.clone())
                .and_modify(|e| {
                    if r.score > e.score {
                        *e = r.clone();
                    }
                })
                .or_insert(r);
        }

        let mut results: Vec<RagResult> = best.into_values().collect();
        results.sort_by(|a, b| {
            b.score
                .partial_cmp(&a.score)
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        results.truncate(limit as usize);
        Ok(results)
    }

    /// Index a single in-memory source file (live workspace indexing).
    ///
    /// Unlike `ingest_repomix_entry`, this takes raw file content directly so a
    /// changed buffer can be re-indexed without a repomix zip. Enrichment,
    /// chunking, embedding, and upsert are identical to the repomix path.
    /// subid: `src.software.workspace.index@v1`
    #[tracing::instrument(skip(self, content), fields(repo, file_path, collection))]
    pub async fn ingest_source_text(
        &self,
        repo: &str,
        file_path: &str,
        content: &str,
        collection: &str,
    ) -> Result<IngestStats> {
        self.ensure_collection(collection).await?;

        let lines: Vec<String> = content.lines().map(str::to_string).collect();
        let meta = enrich(file_path, &lines);
        let chunks = build_chunks(repo, file_path, meta, lines);

        let mut stats = IngestStats {
            files_parsed: 1,
            ..Default::default()
        };
        let mut batch: Vec<PointStruct> = Vec::new();

        for chunk in chunks {
            stats.chunks_created += 1;

            let vector = match self.embed_document(&chunk.embed_text).await {
                Ok(v) => v,
                Err(e) => {
                    warn!(file = %chunk.file_path, error = %e, "Embed failed, skipping chunk");
                    stats.errors += 1;
                    continue;
                }
            };

            let payload: Payload = serde_json::json!({
                "repo":          chunk.repo,
                "file_path":     chunk.file_path,
                "language":      chunk.meta.language,
                "file_type":     chunk.meta.file_type.as_str(),
                "symbols":       chunk.meta.symbols,
                "doc_comments":  chunk.meta.doc_comments,
                "imports":       chunk.meta.imports,
                "tags":          chunk.meta.tags,
                "is_test":       chunk.meta.is_test,
                "line_start":    chunk.line_start,
                "line_end":      chunk.line_end,
                "chunk_index":   chunk.chunk_index,
                "total_chunks":  chunk.total_chunks,
                "content":       chunk.content,
                "content_hash":  chunk.content_hash,
            })
            .try_into()
            .context("Failed to build payload")?;

            batch.push(PointStruct::new(
                stable_uuid(&chunk.content_hash),
                vector,
                payload,
            ));

            if batch.len() >= VOYAGE_BATCH {
                self.flush_batch(collection, &mut batch, &mut stats).await;
                tokio::time::sleep(Duration::from_millis(VOYAGE_RATE_DELAY_MS)).await;
            }
        }

        if !batch.is_empty() {
            self.flush_batch(collection, &mut batch, &mut stats).await;
        }

        info!(
            repo = %repo,
            file = %file_path,
            chunks = stats.chunks_created,
            upserted = stats.chunks_upserted,
            "Live source ingest complete"
        );

        Ok(stats)
    }

    // ─── private ─────────────────────────────────────────────────────────────

    async fn ensure_collection(&self, name: &str) -> Result<()> {
        if !self.qdrant.collection_exists(name).await? {
            match self
                .qdrant
                .create_collection(CreateCollectionBuilder::new(name).vectors_config(
                    VectorsConfig {
                        config: Some(VectorsConfigEnum::Params(
                            VectorParamsBuilder::new(VECTOR_DIM, Distance::Cosine).build(),
                        )),
                    },
                ))
                .await
            {
                Ok(_) => info!(collection = %name, "Created Qdrant collection"),
                Err(err) if is_already_exists(&err) => {
                    tracing::debug!(
                        collection = %name,
                        "Qdrant collection was created concurrently"
                    );
                }
                Err(err) => return Err(err.into()),
            }
        }
        Ok(())
    }

    async fn flush_batch(
        &self,
        collection: &str,
        batch: &mut Vec<PointStruct>,
        stats: &mut IngestStats,
    ) {
        let count = batch.len();
        match self
            .qdrant
            .upsert_points(UpsertPointsBuilder::new(collection, std::mem::take(batch)))
            .await
        {
            Ok(_) => stats.chunks_upserted += count,
            Err(e) => {
                warn!(error = %e, "Qdrant upsert failed");
                stats.errors += 1;
            }
        }
    }

    async fn embed_document(&self, text: &str) -> Result<Vec<f32>> {
        self.embed(text, "document").await
    }

    async fn embed_query(&self, text: &str) -> Result<Vec<f32>> {
        self.embed(text, "query").await
    }

    async fn embed(&self, text: &str, input_type: &str) -> Result<Vec<f32>> {
        #[derive(Serialize)]
        struct Req<'a> {
            input: Vec<&'a str>,
            model: &'a str,
            input_type: &'a str,
            truncation: bool,
            output_dimension: u64,
        }
        #[derive(Deserialize)]
        struct Resp {
            data: Vec<EmbData>,
        }
        #[derive(Deserialize)]
        struct EmbData {
            embedding: Vec<f32>,
        }

        let url = voyage_url_for_key(&self.voyage_key);

        let resp: Resp = self
            .http
            .post(url)
            .bearer_auth(&self.voyage_key)
            .json(&Req {
                input: vec![text],
                model: &self.voyage_model,
                input_type,
                truncation: true,
                output_dimension: VECTOR_DIM,
            })
            .send()
            .await?
            .error_for_status()?
            .json()
            .await?;

        resp.data
            .into_iter()
            .next()
            .map(|d| d.embedding)
            .context("Voyage returned no embeddings")
    }
}

fn is_already_exists(err: &QdrantError) -> bool {
    match err {
        QdrantError::ResponseError { status }
        | QdrantError::ResourceExhaustedError { status, .. } => {
            status.code() == tonic::Code::AlreadyExists
        }
        _ => false,
    }
}

// ─── repomix streaming parser ─────────────────────────────────────────────────

/// Stream-parse a repomix file and yield enriched, chunked entries.
/// Never loads the whole file into memory.
fn parse_and_chunk(reader: impl BufRead, repo: &str) -> impl Iterator<Item = Chunk> {
    let repo = repo.to_string();
    let mut lines_iter = reader.lines();
    let mut pending: Option<(String, Vec<String>, usize)> = None; // (path, lines, start_lineno)
    let mut output: Vec<Chunk> = Vec::new();
    let mut file_count = 0usize;

    // State machine: collect lines between <file path="..."> and </file>
    while let Some(Ok(line)) = lines_iter.next() {
        file_count += 1;

        if let Some(path) = extract_file_path(&line) {
            pending = Some((path, Vec::new(), file_count));
            continue;
        }

        if line.trim() == "</file>" {
            if let Some((path, content_lines, _start)) = pending.take() {
                let meta = enrich(&path, &content_lines);
                let chunks = build_chunks(&repo, &path, meta, content_lines);
                output.extend(chunks);
            }
            continue;
        }

        if let Some((_, ref mut lines, _)) = pending {
            lines.push(line);
        }
    }

    output.into_iter()
}

fn extract_file_path(line: &str) -> Option<String> {
    let trimmed = line.trim();
    if !trimmed.starts_with("<file path=\"") {
        return None;
    }
    let rest = trimmed.strip_prefix("<file path=\"")?;
    let end = rest.find('"')?;
    Some(rest[..end].to_string())
}

// ─── enrichment ───────────────────────────────────────────────────────────────

fn enrich(file_path: &str, lines: &[String]) -> FileMeta {
    let language = detect_language(file_path);
    let file_type = classify_file(file_path, lines);
    let is_test = file_type == FileType::Test
        || lines
            .iter()
            .any(|l| l.contains("#[test]") || l.contains("#[cfg(test)]"));

    let (symbols, doc_comments, imports) = match language {
        "rust" => extract_rust(lines),
        "typescript" | "javascript" => extract_ts(lines),
        "python" => extract_python(lines),
        "go" => extract_go(lines),
        _ => (vec![], vec![], vec![]),
    };

    let tags = auto_tags(file_path, &symbols, &imports, language);

    FileMeta {
        language,
        file_type,
        symbols,
        doc_comments,
        imports,
        tags,
        is_test,
    }
}

fn detect_language(path: &str) -> &'static str {
    let ext = path.rsplit('.').next().unwrap_or("");
    match ext {
        "rs" => "rust",
        "ts" | "tsx" => "typescript",
        "js" | "jsx" | "mjs" => "javascript",
        "py" => "python",
        "go" => "go",
        "proto" => "protobuf",
        "toml" => "toml",
        "yaml" | "yml" => "yaml",
        "json" => "json",
        "md" | "mdx" => "markdown",
        "sh" | "bash" => "shell",
        "c" | "h" => "c",
        "cpp" | "cc" | "cxx" | "hpp" => "cpp",
        "java" => "java",
        "kt" => "kotlin",
        "nix" => "nix",
        _ => "text",
    }
}

fn classify_file(path: &str, lines: &[String]) -> FileType {
    let lower = path.to_lowercase();
    if lower.contains("test") || lower.contains("spec") || lower.ends_with("_test.rs") {
        return FileType::Test;
    }
    if lower.ends_with("cargo.toml")
        || lower.ends_with("package.json")
        || lower.ends_with("pyproject.toml")
        || lower.ends_with("go.mod")
        || lower.ends_with("build.rs")
        || lower.ends_with("makefile")
    {
        return FileType::Build;
    }
    if lower.ends_with(".md") || lower.ends_with(".rst") || lower.ends_with(".txt") {
        return FileType::Docs;
    }
    if lower.ends_with(".toml")
        || lower.ends_with(".yaml")
        || lower.ends_with(".yml")
        || lower.ends_with(".json")
        || lower.ends_with(".env")
    {
        return FileType::Config;
    }
    if lines
        .iter()
        .any(|l| l.contains("#[cfg(test)]") || l.contains("#[test]"))
    {
        return FileType::Test;
    }
    FileType::Source
}

// Rust symbol extraction
fn extract_rust(lines: &[String]) -> (Vec<String>, Vec<String>, Vec<String>) {
    static RE_ITEM: OnceLock<Regex> = OnceLock::new();
    static RE_USE: OnceLock<Regex> = OnceLock::new();

    let re_item = RE_ITEM.get_or_init(|| {
        Regex::new(
            r"^\s*pub(?:\(crate\))?\s+(fn|struct|enum|trait|type|mod|const|static|impl)\s+(\w+)",
        )
        .expect("static regex pattern is valid")
    });
    let re_use = RE_USE.get_or_init(|| {
        Regex::new(r"^\s*use\s+([\w::{}, ]+);").expect("static regex pattern is valid")
    });

    let mut symbols = Vec::new();
    let mut doc_comments = Vec::new();
    let mut imports = Vec::new();
    let mut pending_doc: Vec<String> = Vec::new();

    for line in lines {
        let trimmed = line.trim();

        if trimmed.starts_with("///") || trimmed.starts_with("//!") {
            let doc = trimmed.trim_start_matches('/').trim().to_string();
            if !doc.is_empty() {
                pending_doc.push(doc);
            }
            continue;
        }

        if let Some(caps) = re_item.captures(trimmed) {
            let kind = caps.get(1).map(|m| m.as_str()).unwrap_or("");
            let name = caps.get(2).map(|m| m.as_str()).unwrap_or("");
            symbols.push(format!("{kind} {name}"));
            if !pending_doc.is_empty() {
                doc_comments.push(pending_doc.join(" "));
                pending_doc.clear();
            }
            continue;
        }

        if let Some(caps) = re_use.captures(trimmed) {
            let import = caps.get(1).map(|m| m.as_str()).unwrap_or("").to_string();
            // Only keep top-level crate (first segment)
            let top = import.split("::").next().unwrap_or(&import);
            let top = top.trim_matches('{').trim().to_string();
            if !top.is_empty() && !imports.contains(&top) {
                imports.push(top);
            }
            continue;
        }

        pending_doc.clear();
    }

    // Cap to avoid huge payloads
    symbols.truncate(40);
    doc_comments.truncate(10);
    imports.truncate(30);

    (symbols, doc_comments, imports)
}

fn extract_ts(lines: &[String]) -> (Vec<String>, Vec<String>, Vec<String>) {
    static RE_EXPORT: OnceLock<Regex> = OnceLock::new();
    static RE_IMPORT: OnceLock<Regex> = OnceLock::new();

    let re_export = RE_EXPORT.get_or_init(|| {
        Regex::new(r"^export\s+(?:default\s+)?(?:async\s+)?(?:function|class|interface|type|const|enum)\s+(\w+)").expect("static regex pattern is valid")
    });
    let re_import = RE_IMPORT.get_or_init(|| {
        Regex::new(r#"^import\s+.+from\s+['"]([^'"]+)['"]"#).expect("static regex pattern is valid")
    });

    let mut symbols = Vec::new();
    let mut imports = Vec::new();
    let mut doc_comments = Vec::new();

    for line in lines {
        let trimmed = line.trim();
        if let Some(caps) = re_export.captures(trimmed) {
            symbols.push(caps.get(1).map(|m| m.as_str()).unwrap_or("").to_string());
        }
        if let Some(caps) = re_import.captures(trimmed) {
            let src = caps.get(1).map(|m| m.as_str()).unwrap_or("").to_string();
            let pkg = src.split('/').next().unwrap_or(&src);
            let pkg = pkg.trim_start_matches('@').to_string();
            if !imports.contains(&pkg) {
                imports.push(pkg);
            }
        }
        if trimmed.starts_with("/**") || trimmed.starts_with("* ") {
            let doc = trimmed.trim_start_matches(['/', '*', ' ']).to_string();
            if !doc.is_empty() {
                doc_comments.push(doc);
            }
        }
    }

    symbols.truncate(40);
    doc_comments.truncate(10);
    imports.truncate(30);
    (symbols, doc_comments, imports)
}

fn extract_python(lines: &[String]) -> (Vec<String>, Vec<String>, Vec<String>) {
    static RE_DEF: OnceLock<Regex> = OnceLock::new();
    static RE_IMP: OnceLock<Regex> = OnceLock::new();

    let re_def = RE_DEF.get_or_init(|| {
        Regex::new(r"^(?:class|def|async def)\s+(\w+)").expect("static regex pattern is valid")
    });
    let re_imp = RE_IMP.get_or_init(|| {
        Regex::new(r"^(?:import|from)\s+([\w.]+)").expect("static regex pattern is valid")
    });

    let mut symbols = Vec::new();
    let mut imports = Vec::new();

    for line in lines {
        let trimmed = line.trim();
        if let Some(caps) = re_def.captures(trimmed) {
            symbols.push(caps.get(1).map(|m| m.as_str()).unwrap_or("").to_string());
        }
        if let Some(caps) = re_imp.captures(trimmed) {
            let pkg = caps.get(1).map(|m| m.as_str()).unwrap_or("").to_string();
            let top = pkg.split('.').next().unwrap_or(&pkg).to_string();
            if !imports.contains(&top) {
                imports.push(top);
            }
        }
    }

    symbols.truncate(40);
    imports.truncate(30);
    (symbols, vec![], imports)
}

fn extract_go(lines: &[String]) -> (Vec<String>, Vec<String>, Vec<String>) {
    static RE_DECL: OnceLock<Regex> = OnceLock::new();
    static RE_IMP: OnceLock<Regex> = OnceLock::new();

    let re_decl = RE_DECL.get_or_init(|| {
        Regex::new(r"^func\s+(?:\(\w+\s+\*?\w+\)\s+)?(\w+)|^type\s+(\w+)\s+(?:struct|interface)")
            .expect("static regex pattern is valid")
    });
    let re_imp = RE_IMP
        .get_or_init(|| Regex::new(r#"^\s+"([^"]+)""#).expect("static regex pattern is valid"));

    let mut symbols = Vec::new();
    let mut imports = Vec::new();

    for line in lines {
        let trimmed = line.trim();
        if let Some(caps) = re_decl.captures(trimmed) {
            let name = caps
                .get(1)
                .or_else(|| caps.get(2))
                .map(|m| m.as_str())
                .unwrap_or("")
                .to_string();
            if !name.is_empty() {
                symbols.push(name);
            }
        }
        if let Some(caps) = re_imp.captures(trimmed) {
            let pkg = caps.get(1).map(|m| m.as_str()).unwrap_or("");
            let top = pkg.split('/').next_back().unwrap_or(pkg).to_string();
            if !imports.contains(&top) {
                imports.push(top);
            }
        }
    }

    symbols.truncate(40);
    imports.truncate(30);
    (symbols, vec![], imports)
}

fn auto_tags(path: &str, symbols: &[String], imports: &[String], lang: &str) -> Vec<String> {
    let mut tags: Vec<&str> = Vec::new();

    // Language tag
    tags.push(lang);

    // Path-based tags
    let lower = path.to_lowercase();
    for keyword in [
        "server", "client", "handler", "router", "auth", "error", "config", "test", "bench",
        "proto", "grpc", "http", "async", "stream", "channel", "database", "cache",
    ] {
        if lower.contains(keyword) {
            tags.push(keyword);
        }
    }

    // Symbol-based tags
    let sym_text = symbols.join(" ").to_lowercase();
    for keyword in [
        "trait", "impl", "async", "handler", "service", "client", "server", "error", "config",
        "builder", "stream",
    ] {
        if sym_text.contains(keyword) {
            tags.push(keyword);
        }
    }

    // Import-based tags
    for imp in imports {
        match imp.as_str() {
            "tokio" | "async_std" => tags.push("async"),
            "tonic" | "prost" => tags.push("grpc"),
            "axum" | "hyper" | "actix" | "warp" => tags.push("http"),
            "serde" | "serde_json" => tags.push("serialization"),
            "sqlx" | "diesel" | "sea_orm" => tags.push("database"),
            "tracing" | "log" => tags.push("logging"),
            "anyhow" | "thiserror" => tags.push("error-handling"),
            _ => {}
        }
    }

    let mut deduped: Vec<String> = Vec::new();
    for t in tags {
        let s = t.to_string();
        if !deduped.contains(&s) {
            deduped.push(s);
        }
    }
    deduped.truncate(20);
    deduped
}

// ─── chunking ─────────────────────────────────────────────────────────────────

fn build_chunks(repo: &str, file_path: &str, meta: FileMeta, lines: Vec<String>) -> Vec<Chunk> {
    if lines.is_empty() {
        return vec![];
    }

    let mut chunks = Vec::new();
    let step = CHUNK_LINES.saturating_sub(OVERLAP_LINES).max(1);
    let total = ((lines.len() as f64) / step as f64).ceil() as usize;
    let total = total.max(1);

    let mut idx = 0usize;
    let mut chunk_index = 0usize;
    while idx < lines.len() {
        let end = (idx + CHUNK_LINES).min(lines.len());
        let chunk_lines = &lines[idx..end];
        let content = chunk_lines.join("\n");
        let embed_text = build_embed_text(repo, file_path, &meta, &content);
        let content_hash =
            hex_hash(format!("{repo}:{file_path}:{chunk_index}:{content}").as_bytes());

        chunks.push(Chunk {
            repo: repo.to_string(),
            file_path: file_path.to_string(),
            meta: meta.clone(),
            content,
            embed_text,
            content_hash,
            chunk_index,
            total_chunks: total,
            line_start: idx + 1,
            line_end: end,
        });

        idx += step;
        chunk_index += 1;

        if end >= lines.len() {
            break;
        }
    }

    chunks
}

/// Build the text that gets embedded — metadata header + content.
/// The header primes the embedding model with structural context.
fn build_embed_text(repo: &str, file_path: &str, meta: &FileMeta, content: &str) -> String {
    let mut header = format!("REPO: {repo}\nFILE: {file_path}\nLANG: {}\n", meta.language);

    if !meta.symbols.is_empty() {
        header.push_str(&format!("SYMBOLS: {}\n", meta.symbols.join(", ")));
    }
    if let Some(first_doc) = meta.doc_comments.first() {
        header.push_str(&format!("DOCS: {}\n", first_doc));
    }
    if !meta.imports.is_empty() {
        header.push_str(&format!("DEPS: {}\n", meta.imports.join(", ")));
    }
    if !meta.tags.is_empty() {
        header.push_str(&format!("TAGS: {}\n", meta.tags.join(", ")));
    }
    if meta.is_test {
        header.push_str("TYPE: test\n");
    }

    format!("{header}---\n{content}")
}

// ─── helpers ──────────────────────────────────────────────────────────────────

fn repo_name_from_entry(entry_name: &str) -> String {
    // "rust-analyzer-repomix.md" → "rust-analyzer"
    // "google-cloud-rust-repomix-2.md" → "google-cloud-rust"
    let base = entry_name.trim_end_matches(".md").trim_end_matches(".xml");

    // Strip trailing "-repomix" and any "-N" suffix
    let base = if let Some(pos) = base.rfind("-repomix") {
        &base[..pos]
    } else {
        base
    };

    base.to_string()
}

fn hex_hash(data: &[u8]) -> String {
    let mut h = Sha256::new();
    h.update(data);
    hex::encode(h.finalize())
}

fn stable_uuid(hash: &str) -> String {
    // Use first 32 hex chars of hash to form a UUID-like stable ID
    if hash.len() >= 32 {
        format!(
            "{}-{}-{}-{}-{}",
            &hash[0..8],
            &hash[8..12],
            &hash[12..16],
            &hash[16..20],
            &hash[20..32]
        )
    } else {
        uuid::Uuid::new_v4().to_string()
    }
}

// ─── Qdrant connection ────────────────────────────────────────────────────────

/// Build a Qdrant client from environment.
///
/// Connection is always TCP to localhost. When the qdrant container socket is
/// declared via `UNIX_SOCKET_ENDPOINTS` (e.g. `qdrant:/run/qdrant.sock:6334`),
/// xray transparently proxies `127.0.0.1:6334` → container unix socket using
/// its native domain-socket (`"network": "ds"`) outbound — no custom tonic
/// connector needed here.
///
/// Override the URL with `COGNITIVE_MCP_QDRANT_URL`.
pub fn qdrant_client_from_env() -> Result<Qdrant> {
    let url = std::env::var("COGNITIVE_MCP_QDRANT_URL")
        .unwrap_or_else(|_| "http://127.0.0.1:6334".into());
    Qdrant::from_url(&url)
        .build()
        .context("Failed to build Qdrant client")
}

/// Load the Voyage API key from a secret file when env vars are unset.
///
/// Defaults to `~/.ssh/mongo-voyage`; override with the
/// `COGNITIVE_MCP_VOYAGE_KEY_FILE` env var. The first non-empty line is used
/// (so a key file with a trailing newline or comment lines works).
fn voyage_key_from_file() -> Option<String> {
    let path = std::env::var("COGNITIVE_MCP_VOYAGE_KEY_FILE")
        .ok()
        .map(std::path::PathBuf::from)
        .or_else(|| std::env::var_os("HOME").map(|h| Path::new(&h).join(".ssh/mongo-voyage")))?;

    let contents = std::fs::read_to_string(&path).ok()?;
    // The creds file may contain multiple credential types (Atlas service
    // account ID/secret, plus a Voyage API key).  We must skip service
    // account lines and pick the actual API key.
    let key = contents
        .lines()
        .map(str::trim)
        .find(|l| {
            !l.is_empty()
                && !l.starts_with('#')
                // skip Atlas service-account tokens
                && !l.starts_with("mdb_sa_id_")
                && !l.starts_with("mdb_sa_sk_")
                // line should look like a Voyage key (MongoDB-hosted or public)
                && (l.starts_with("al-") || l.starts_with("pa-"))
        })?
        .to_string();

    if key.is_empty() {
        None
    } else {
        info!(path = %path.display(), "Loaded Voyage API key from file");
        Some(key)
    }
}

/// Determine the correct Voyage endpoint for a given API key.
fn voyage_url_for_key(key: &str) -> &'static str {
    let trimmed = key.trim();
    if trimmed.starts_with("al-") {
        VOYAGE_MONGODB_URL
    } else {
        VOYAGE_PUBLIC_URL
    }
}

/// Map a scored Qdrant point + payload into a `RagResult`.
fn point_to_result(pt: ScoredPoint) -> RagResult {
    let p = serde_json::to_value(&pt.payload).unwrap_or_default();
    RagResult {
        score: pt.score,
        repo: str_field(&p, "repo"),
        file_path: str_field(&p, "file_path"),
        language: str_field(&p, "language"),
        file_type: str_field(&p, "file_type"),
        symbols: str_arr(&p, "symbols"),
        doc_comments: str_arr(&p, "doc_comments"),
        imports: str_arr(&p, "imports"),
        tags: str_arr(&p, "tags"),
        is_test: p["is_test"].as_bool().unwrap_or(false),
        line_start: p["line_start"].as_i64().unwrap_or(0),
        line_end: p["line_end"].as_i64().unwrap_or(0),
        chunk_index: p["chunk_index"].as_i64().unwrap_or(0),
        total_chunks: p["total_chunks"].as_i64().unwrap_or(1),
        content: str_field(&p, "content"),
    }
}

fn str_field(v: &serde_json::Value, key: &str) -> String {
    v[key].as_str().unwrap_or("").to_string()
}

fn str_arr(v: &serde_json::Value, key: &str) -> Vec<String> {
    v[key]
        .as_array()
        .map(|arr| {
            arr.iter()
                .filter_map(|x| x.as_str().map(str::to_string))
                .collect()
        })
        .unwrap_or_default()
}

//! gRPC Reader: Reading from gRPC services.
//!
//! This module implements the `GrpcReader` trait, discovering gRPC services
//! and projecting methods and message types into raw entities.

use crate::interfaces::{GrpcReader, RawEntity, SourceReader};
use anyhow::Result;
use simd_json::json;
use tracing::debug;

/// Reader that extracts state from gRPC services.
#[derive(Debug)]
pub struct SystemGrpcReader {
    /// Source identifier
    source: String,
}

impl SystemGrpcReader {
    /// Creates a new SystemGrpcReader
    pub fn new() -> Self {
        Self {
            source: "grpc".to_string(),
        }
    }
}

impl Default for SystemGrpcReader {
    fn default() -> Self {
        Self::new()
    }
}

impl SourceReader for SystemGrpcReader {
    fn read_all(&self) -> Result<Vec<RawEntity>> {
        self.read_services()
    }

    fn read_entity(&self, entity_id: &str) -> Result<RawEntity> {
        debug!(entity_id = entity_id, "Reading gRPC entity");
        Ok(RawEntity {
            entity_type: "grpc.service".to_string(),
            entity_id: entity_id.to_string(),
            data: json!({ "methods": [] }),
            source: self.source.clone(),
        })
    }

    fn source_id(&self) -> &str {
        &self.source
    }

    fn is_available(&self) -> bool {
        true
    }
}

impl GrpcReader for SystemGrpcReader {
    fn read_services(&self) -> Result<Vec<RawEntity>> {
        debug!("Discovering gRPC services");
        Ok(Vec::new())
    }

    fn read_methods(&self, service: &str) -> Result<Vec<RawEntity>> {
        debug!(service = service, "Reading gRPC methods");
        Ok(Vec::new())
    }

    fn read_messages(&self, service: &str) -> Result<Vec<RawEntity>> {
        debug!(service = service, "Reading gRPC message types");
        Ok(Vec::new())
    }

    fn read_endpoints(&self) -> Result<Vec<RawEntity>> {
        debug!("Reading gRPC endpoints");
        Ok(Vec::new())
    }
}

//! Canonical Plugin Path and Interface Constants
//!
//! This module defines the SINGLE SOURCE OF TRUTH for all plugin-related
//! paths, interfaces, and naming conventions following FreeDesktop D-Bus
//! standards.
//!
//! ## Canonical Naming Convention
//!
//! ### D-Bus Object Paths
//! ```text
//! /org/opdbus/v1/plugins/{plugin_name}
//! /org/opdbus/v1/plugins/{plugin_name}/{child_object}
//! ```
//!
//! ### D-Bus Interface Names
//! ```text
//! org.opdbus.v1.Plugin.Plugins
//! org.opdbus.v1.Plugin.Plugins.{PluginName}
//! org.opdbus.v1.Plugin.{PluginName}
//! ```
//!
//! ### D-Bus Service Names (Bus Names)
//! ```text
//! org.opdbus.v1
//! org.opdbus.v1.Plugin.{PluginName}
//! ```
//!
//! ### Schema File Paths
//! ```text
//! schemas/plugin/{plugin_name}.json
//! schemas/plugin/freedesktop.json
//! ```
//!
//! ## Forbidden Patterns (DO NOT USE)
//!
//! These patterns are deprecated and MUST NOT be used:
//! - `/opdbus/v1/plugins/` - Missing `org` prefix
//! - `/org/opdbus/plugins/` - Missing `v1` version
//! - `/org/opdbus/v1/` - Missing `plugin` segment
//! - `org.opdbus.plugins.*` - Missing `v1` version
//! - `org.opdbus.v1plugins.*` - Missing dot separator
//!
//! ## Migration Guide
//!
//! Old (deprecated): `/opdbus/v1/plugins/net`
//! New (canonical): `/org/opdbus/v1/plugins/net`
//!
//! Old (deprecated alias): `/org/opdbus/v1/plugin/plugins/net`
//! New (canonical): `/org/opdbus/v1/plugins/net`
//!
//! Old (deprecated): `org.opdbus.NetPlugin`
//! New (canonical): `org.opdbus.v1.Plugin.Plugins.Net`

/// Root D-Bus object path for the op-dbus system
pub const DBUS_ROOT_PATH: &str = "/org/opdbus/v1";

/// Canonical base path for all plugins
pub const PLUGIN_BASE_PATH: &str = "/org/opdbus/v1/plugins";

/// Base interface name for plugin-related interfaces
pub const PLUGIN_BASE_INTERFACE: &str = "org.opdbus.v1.Plugin";

/// Interface for the plugins collection/manager
pub const PLUGINS_INTERFACE: &str = "org.opdbus.v1.Plugin.Plugins";

/// Base service name (bus name)
pub const BASE_SERVICE_NAME: &str = "org.opdbus.v1";

/// Schema file directory for plugins
pub const PLUGIN_SCHEMA_DIR: &str = "schemas/plugin";

/// Meta-schema file for plugin validation
pub const PLUGIN_META_SCHEMA: &str = "schemas/plugin/org.opdbus.plugin.schema.json";

/// FreeDesktop plugin schema
pub const FREEDESKTOP_SCHEMA: &str = "schemas/plugin/freedesktop.json";

/// ObjectManager interface (FreeDesktop standard)
pub const OBJECT_MANAGER_INTERFACE: &str = "org.freedesktop.DBus.ObjectManager";

/// Properties interface (FreeDesktop standard)
pub const PROPERTIES_INTERFACE: &str = "org.freedesktop.DBus.Properties";

/// Introspectable interface (FreeDesktop standard)
pub const INTROSPECTABLE_INTERFACE: &str = "org.freedesktop.DBus.Introspectable";

/// Peer interface (FreeDesktop standard)
pub const PEER_INTERFACE: &str = "org.freedesktop.DBus.Peer";

/// Legacy path prefix - DEPRECATED, for migration only
#[deprecated(
    since = "2.0.0",
    note = "Use PLUGIN_BASE_PATH instead. Legacy paths will be removed in v3.0.0"
)]
pub const LEGACY_PLUGIN_PATH: &str = "/opdbus/v1/plugins";

/// Alternative legacy path - DEPRECATED, for migration only
#[deprecated(
    since = "2.0.0",
    note = "Use PLUGIN_BASE_PATH instead. Legacy paths will be removed in v3.0.0"
)]
pub const LEGACY_ALT_PLUGIN_PATH: &str = "/org/opdbus/v1/plugin/plugins";

/// Build the full D-Bus object path for a plugin
///
/// # Example
/// ```
/// use op_plugins::canonical::plugin_path;
///
/// let path = plugin_path("incus");
/// assert_eq!(path, "/org/opdbus/v1/plugins/incus");
/// ```
pub fn plugin_path(name: &str) -> String {
    format!("{}/{}", PLUGIN_BASE_PATH, sanitize_plugin_name(name))
}

/// Build the D-Bus interface name for a specific plugin
///
/// # Example
/// ```
/// use op_plugins::canonical::plugin_interface;
///
/// let iface = plugin_interface("incus");
/// assert_eq!(iface, "org.opdbus.v1.Plugin.Plugins.Incus");
/// ```
pub fn plugin_interface(name: &str) -> String {
    let sanitized = sanitize_plugin_name(name);
    let capitalized = capitalize_plugin_name(&sanitized);
    format!("{}.{}", PLUGINS_INTERFACE, capitalized)
}

/// Build the schema file path for a plugin
///
/// # Example
/// ```
/// use op_plugins::canonical::plugin_schema_path;
///
/// let path = plugin_schema_path("incus");
/// assert_eq!(path, "schemas/plugin/incus.json");
/// ```
pub fn plugin_schema_path(name: &str) -> String {
    format!("{}/{}.json", PLUGIN_SCHEMA_DIR, sanitize_plugin_name(name))
}

/// Build a child object path under a plugin
///
/// # Example
/// ```
/// use op_plugins::canonical::plugin_child_path;
///
/// let path = plugin_child_path("incus", "instance-1");
/// assert_eq!(path, "/org/opdbus/v1/plugins/incus/instance-1");
/// ```
pub fn plugin_child_path(plugin_name: &str, child_id: &str) -> String {
    format!(
        "{}/{}/{}",
        PLUGIN_BASE_PATH,
        sanitize_plugin_name(plugin_name),
        sanitize_child_id(child_id)
    )
}

/// Sanitize a plugin name for use in paths and interface names
///
/// Rules:
/// - Convert to lowercase
/// - Replace hyphens with underscores
/// - Remove any leading/trailing slashes
/// - Must start with a letter (a-z)
pub fn sanitize_plugin_name(name: &str) -> String {
    let sanitized = name
        .trim()
        .trim_matches('/')
        .to_lowercase()
        .replace('-', "_");

    // Ensure it starts with a letter
    if sanitized
        .chars()
        .next()
        .map(|c| c.is_ascii_digit())
        .unwrap_or(false)
    {
        format!("plugin_{}", sanitized)
    } else {
        sanitized
    }
}

/// Capitalize a plugin name for use in interface names
///
/// Converts `plugin_name` to `PluginName`
pub fn capitalize_plugin_name(name: &str) -> String {
    name.split('_')
        .map(|word| {
            let mut chars = word.chars();
            match chars.next() {
                None => String::new(),
                Some(first) => {
                    first.to_uppercase().collect::<String>() + &chars.as_str().to_lowercase()
                }
            }
        })
        .collect()
}

/// Sanitize a child object ID for use in paths
///
/// Rules:
/// - Must not contain path separators
/// - Must be valid UTF-8
/// - Length must be <= 255 characters
fn sanitize_child_id(id: &str) -> String {
    let sanitized: String = id
        .chars()
        .filter(|c| *c != '/' && *c != '\\' && !c.is_control())
        .take(255)
        .collect();

    if sanitized.is_empty() {
        "_".to_string()
    } else {
        sanitized
    }
}

/// Validate a plugin path is in canonical form
///
/// Returns true if the path follows the canonical convention
pub fn is_canonical_plugin_path(path: &str) -> bool {
    path.starts_with(PLUGIN_BASE_PATH)
}

/// Normalize a plugin path to canonical form
///
/// Converts legacy paths to canonical paths
///
/// # Examples
/// - `/opdbus/v1/plugins/net` → `/org/opdbus/v1/plugins/net`
/// - `/org/opdbus/v1/plugin/plugins/net` → `/org/opdbus/v1/plugins/net`
/// - `/org/opdbus/v1/plugins/net` → `/org/opdbus/v1/plugins/net` (already canonical)
pub fn normalize_plugin_path(path: &str) -> Option<String> {
    let trimmed = path.trim().trim_matches('/');

    // Already canonical
    if trimmed.starts_with("org/opdbus/v1/plugins/") {
        return Some(format!("/{}", trimmed));
    }

    // Legacy alias: /org/opdbus/v1/plugin/plugins/{name}
    if let Some(rest) = trimmed.strip_prefix("org/opdbus/v1/plugin/plugins/") {
        let name = rest.split('/').next()?;
        return Some(plugin_path(name));
    }

    // Legacy: /opdbus/v1/plugins/{name}
    if let Some(rest) = trimmed.strip_prefix("opdbus/v1/plugins/") {
        let name = rest.split('/').next()?;
        return Some(plugin_path(name));
    }

    // Just a plugin name
    if !trimmed.contains('/') {
        return Some(plugin_path(trimmed));
    }

    None
}

/// Extract plugin name from a path (canonical or legacy)
///
/// # Examples
/// - `/org/opdbus/v1/plugins/net` → `Some("net")`
/// - `/opdbus/v1/plugins/net` → `Some("net")` (legacy)
/// - `/other/path` → `None`
pub fn extract_plugin_name(path: &str) -> Option<String> {
    let normalized = normalize_plugin_path(path)?;
    normalized
        .strip_prefix(PLUGIN_BASE_PATH)?
        .trim_start_matches('/')
        .split('/')
        .next()
        .map(|s| s.to_string())
}

