//! D-Bus side of the Assistant gateway. Exposes a generic `call(method,
//! payload_json) -> response_json` surface so the gRPC side can dispatch
//! Assistant operations through D-Bus when available.
//!
//! Authentication is delegated to the bus policy files (`/usr/share/dbus-1/
//! system.d/ai.assistant.v1.conf`).

use crate::client::AssistantClient;
use crate::transport::{DEFAULT_DBUS_NAME, DEFAULT_DBUS_PATH};
use std::sync::Arc;
use zbus::object_server::SignalEmitter;

pub struct AssistantDbusService {
    client: Arc<AssistantClient>,
}

impl AssistantDbusService {
    pub fn new(client: Arc<AssistantClient>) -> Self {
        Self { client }
    }
}

#[zbus::interface(name = "ai.assistant.v1")]
impl AssistantDbusService {
    /// Generic JSON-RPC style passthrough. Returns the JSON-encoded response
    /// from the Assistant gateway.
    async fn call(&self, method: String, payload_json: String) -> zbus::fdo::Result<String> {
        let params: serde_json::Value = serde_json::from_str(&payload_json)
            .map_err(|e| zbus::fdo::Error::InvalidArgs(format!("invalid json: {}", e)))?;
        let result = self
            .client
            .call(&method, params)
            .await
            .map_err(|e| zbus::fdo::Error::Failed(e.to_string()))?;
        Ok(result.to_string())
    }

    /// Signal fired whenever an Assistant run emits an event. The gRPC side
    /// can subscribe to this signal to relay events to gRPC streaming clients.
    #[zbus(signal)]
    pub async fn run_event(
        emitter: &SignalEmitter<'_>,
        run_id: String,
        event_json: String,
    ) -> zbus::Result<()>;
}

/// Publish the D-Bus interface on the session bus. Returns the held connection
/// so callers can keep it alive.
pub async fn serve(client: Arc<AssistantClient>) -> zbus::Result<zbus::Connection> {
    let name = std::env::var("OP_ASSISTANT_DBUS_NAME").unwrap_or_else(|_| DEFAULT_DBUS_NAME.into());
    let path = std::env::var("OP_ASSISTANT_DBUS_PATH").unwrap_or_else(|_| DEFAULT_DBUS_PATH.into());

    let svc = AssistantDbusService::new(client);
    let conn = zbus::connection::Builder::session()?
        .name(name.as_str())?
        .serve_at(path.as_str(), svc)?
        .build()
        .await?;
    Ok(conn)
}

//! Plugin Reader: Reading from plugins.
//!
//! This module implements the `PluginReader` trait by loading the default
//! runtime plugins, querying their live state, and emitting both top-level
//! plugin state entities and nested object projections.

use crate::data_models::{FieldSchema, FieldType, PluginSchema};
use crate::interfaces::{PluginLifecycleEvent, PluginReader, RawEntity, SourceReader};
use anyhow::{Context, Result};
use op_plugins::DefaultPluginRegistry;
use op_state::StatePlugin;
use op_state_store::{MemoryStore, StateStore};
use simd_json::prelude::*;
use simd_json::{json, OwnedValue as Value};
use std::future::Future;
use std::sync::Arc;
use tracing::{debug, info, warn};

struct LoadedPlugin {
    name: String,
    schema: Option<PluginSchema>,
    plugin: Arc<dyn StatePlugin>,
}

/// Reader that extracts live state from runtime plugins.
pub struct SystemPluginReader {
    /// Source identifier
    source: String,
    /// Loaded runtime plugins and their resolved schemas
    plugins: Vec<LoadedPlugin>,
}

impl std::fmt::Debug for SystemPluginReader {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let plugin_names: Vec<&str> = self
            .plugins
            .iter()
            .map(|plugin| plugin.name.as_str())
            .collect();
        f.debug_struct("SystemPluginReader")
            .field("source", &self.source)
            .field("plugins", &plugin_names)
            .finish()
    }
}

impl SystemPluginReader {
    /// Creates an empty reader when plugin bootstrap is unavailable.
    pub fn empty() -> Self {
        Self {
            source: "plugin".to_string(),
            plugins: Vec::new(),
        }
    }

    /// Creates a new SystemPluginReader backed by the default runtime plugins.
    /// Uses MemoryStore — no SQLite, zero drift. Current state = desired state.
    pub async fn new() -> Result<Self> {
        let state_store: Arc<dyn StateStore> = Arc::new(MemoryStore::new());

        let registry = DefaultPluginRegistry::new(state_store);
        let plugins = registry.load_all_plugins().await?;
        let plugins = plugins
            .into_iter()
            .map(|plugin| {
                let name = plugin.name().to_string();
                let schema = Self::plugin_owned_schema(&name, plugin.schema());

                if schema.is_none() {
                    warn!(
                        plugin_id = %name,
                        "Plugin has no PluginSchema; top-level state will be projected without plugin-specific validation"
                    );
                }

                LoadedPlugin { name, schema, plugin }
            })
            .collect::<Vec<_>>();

        info!(
            plugin_count = plugins.len(),
            "Initialized plugin projection reader"
        );

        Ok(Self {
            source: "plugin".to_string(),
            plugins,
        })
    }

    /// The schema used to validate nested plugin object projections.
    pub fn nested_object_projection_schema() -> PluginSchema {
        let read_only_string = |description: &str| FieldSchema {
            field_type: FieldType::String,
            required: true,
            description: description.to_string(),
            default: None,
            example: None,
            constraints: Vec::new(),
            read_only: true,
            read_only_when: None,
        };

        PluginSchema::builder("plugin.object")
            .version("1.0.0")
            .category("plugin")
            .field("plugin_id", read_only_string("Owning plugin identifier"))
            .field("parent_id", read_only_string("Parent projection entity ID"))
            .field(
                "object_path",
                read_only_string("JSON pointer-like path to the nested object"),
            )
            .field(
                "value",
                FieldSchema {
                    field_type: FieldType::Any,
                    required: true,
                    description: "Nested object value mirrored from plugin state".to_string(),
                    default: None,
                    example: None,
                    constraints: Vec::new(),
                    read_only: true,
                    read_only_when: None,
                },
            )
            .build()
    }

    /// Returns all schemas required for plugin state projection.
    ///
    /// Plugin schemas are the canonical `PluginSchema` directly — no conversion:
    /// the plugin is the schema.
    pub fn projection_schemas(&self) -> Vec<PluginSchema> {
        let mut schemas = self
            .plugins
            .iter()
            .filter_map(|plugin| plugin.schema.clone())
            .collect::<Vec<_>>();
        schemas.push(Self::nested_object_projection_schema());
        schemas
    }

    /// Reads all plugin-backed projection entities asynchronously.
    pub async fn read_all_async(&self) -> Result<Vec<RawEntity>> {
        let mut entities = Vec::new();

        for plugin in &self.plugins {
            entities.extend(self.read_loaded_plugin(plugin).await?);
        }

        debug!(
            entity_count = entities.len(),
            "Read plugin projection entities"
        );
        Ok(entities)
    }

    /// Reads all projection entities for a single plugin asynchronously.
    pub async fn read_plugin_objects_async(&self, plugin_id: &str) -> Result<Vec<RawEntity>> {
        let requested_id = DefaultPluginRegistry::resolve_requested_plugin_name(plugin_id)
            .with_context(|| format!("invalid plugin request '{}'", plugin_id))?;
        let requested_plugin;
        let plugin = match self
            .plugins
            .iter()
            .find(|plugin| plugin.name == requested_id)
        {
            Some(plugin) => plugin,
            None => {
                requested_plugin = Self::load_requested_plugin(&requested_id).await?;
                &requested_plugin
            }
        };

        self.read_loaded_plugin(plugin).await
    }

    async fn load_requested_plugin(plugin_id: &str) -> Result<LoadedPlugin> {
        let state_store: Arc<dyn StateStore> = Arc::new(MemoryStore::new());
        let registry = DefaultPluginRegistry::new(state_store);
        let plugin = registry
            .load_plugin(plugin_id)
            .await
            .with_context(|| format!("failed to auto-load requested plugin '{}'", plugin_id))?;
        let name = plugin.name().to_string();
        let schema = Self::plugin_owned_schema(&name, plugin.schema());

        Ok(LoadedPlugin {
            name,
            schema,
            plugin,
        })
    }

    fn plugin_owned_schema(plugin_id: &str, schema: Option<PluginSchema>) -> Option<PluginSchema> {
        match schema {
            Some(schema) if schema.name == plugin_id => Some(schema),
            Some(schema) => {
                warn!(
                    plugin_id,
                    schema_name = %schema.name,
                    "Ignoring schema whose name does not match the owning plugin"
                );
                None
            }
            None => None,
        }
    }

    /// Reads nested object projections for a single plugin asynchronously.
    pub async fn read_nested_objects_async(
        &self,
        plugin_id: &str,
        parent_id: &str,
    ) -> Result<Vec<RawEntity>> {
        let entities = self.read_plugin_objects_async(plugin_id).await?;

        Ok(entities
            .into_iter()
            .filter(|entity| {
                entity.entity_type == "plugin.object"
                    && entity
                        .data
                        .get("parent_id")
                        .and_then(|value| value.as_str())
                        == Some(parent_id)
            })
            .collect())
    }

    async fn read_loaded_plugin(&self, plugin: &LoadedPlugin) -> Result<Vec<RawEntity>> {
        let state = match plugin.plugin.query_current_state().await {
            Ok(state) => state,
            Err(error) => {
                warn!(
                    plugin_id = %plugin.name,
                    error = %error,
                    "Skipping plugin projection because state query failed"
                );
                return Ok(Vec::new());
            }
        };

        let mut entities = vec![RawEntity {
            entity_type: plugin.name.clone(),
            entity_id: plugin.name.clone(),
            data: state.clone(),
            source: self.source.clone(),
        }];

        entities.extend(Self::collect_nested_entities(
            &plugin.name,
            &state,
            &self.source,
        ));

        Ok(entities)
    }

    fn collect_nested_entities(plugin_id: &str, state: &Value, source: &str) -> Vec<RawEntity> {
        let mut entities = Vec::new();
        Self::collect_nested_entities_recursive(
            &mut entities,
            plugin_id,
            plugin_id,
            "",
            state,
            source,
        );
        entities
    }

    fn collect_nested_entities_recursive(
        entities: &mut Vec<RawEntity>,
        plugin_id: &str,
        parent_id: &str,
        path: &str,
        value: &Value,
        source: &str,
    ) {
        match value {
            Value::Object(map) => {
                if !path.is_empty() {
                    entities.push(RawEntity {
                        entity_type: "plugin.object".to_string(),
                        entity_id: Self::nested_entity_id(plugin_id, path),
                        data: json!({
                            "plugin_id": plugin_id,
                            "parent_id": parent_id,
                            "object_path": path,
                            "value": value.clone(),
                        }),
                        source: source.to_string(),
                    });
                }

                let current_id = if path.is_empty() {
                    plugin_id.to_string()
                } else {
                    Self::nested_entity_id(plugin_id, path)
                };

                for (key, child) in map.iter() {
                    if child.is_object() || child.is_array() {
                        let child_path = format!("{}/{}", path, key);
                        Self::collect_nested_entities_recursive(
                            entities,
                            plugin_id,
                            &current_id,
                            &child_path,
                            child,
                            source,
                        );
                    }
                }
            }
            Value::Array(array) => {
                if !path.is_empty() {
                    entities.push(RawEntity {
                        entity_type: "plugin.object".to_string(),
                        entity_id: Self::nested_entity_id(plugin_id, path),
                        data: json!({
                            "plugin_id": plugin_id,
                            "parent_id": parent_id,
                            "object_path": path,
                            "value": value.clone(),
                        }),
                        source: source.to_string(),
                    });
                }

                let current_id = if path.is_empty() {
                    plugin_id.to_string()
                } else {
                    Self::nested_entity_id(plugin_id, path)
                };

                for (index, child) in array.iter().enumerate() {
                    if child.is_object() || child.is_array() {
                        // Use the object's "id" field as the path segment when available,
                        // so D-Bus paths are named (e.g. /providers/antigravity) instead of
                        // opaque numeric indexes (e.g. /providers/3).
                        let segment = ["id", "name", "label", "key", "path", "domain", "host"]
                            .iter()
                            .find_map(|&field| child.get(field).and_then(|v| v.as_str()))
                            .map(|s| s.replace(['/', ' ', ':'], "_"))
                            .unwrap_or_else(|| index.to_string());
                        let child_path = format!("{}/{}", path, segment);
                        Self::collect_nested_entities_recursive(
                            entities,
                            plugin_id,
                            &current_id,
                            &child_path,
                            child,
                            source,
                        );
                    }
                }
            }
            _ => {}
        }
    }

    fn nested_entity_id(plugin_id: &str, path: &str) -> String {
        format!("{}:{}", plugin_id, path)
    }

    fn block_on<F, T>(&self, future: F) -> Result<T>
    where
        F: Future<Output = Result<T>>,
    {
        match tokio::runtime::Handle::try_current() {
            Ok(handle) => tokio::task::block_in_place(|| handle.block_on(future)),
            Err(_) => {
                let runtime = tokio::runtime::Builder::new_current_thread()
                    .enable_all()
                    .build()
                    .context("failed to build a tokio runtime for plugin projection")?;
                runtime.block_on(future)
            }
        }
    }
}

impl Default for SystemPluginReader {
    fn default() -> Self {
        Self::empty()
    }
}

impl SourceReader for SystemPluginReader {
    fn read_all(&self) -> Result<Vec<RawEntity>> {
        self.block_on(self.read_all_async())
    }

    fn read_entity(&self, entity_id: &str) -> Result<RawEntity> {
        let entities = self.block_on(self.read_all_async())?;
        entities
            .into_iter()
            .find(|entity| entity.entity_id == entity_id)
            .with_context(|| format!("unknown plugin entity '{}'", entity_id))
    }

    fn source_id(&self) -> &str {
        &self.source
    }

    fn is_available(&self) -> bool {
        !self.plugins.is_empty()
    }
}

impl PluginReader for SystemPluginReader {
    fn read_plugin_objects(&self, plugin_id: &str) -> Result<Vec<RawEntity>> {
        debug!(plugin_id = plugin_id, "Reading plugin objects");
        self.block_on(self.read_plugin_objects_async(plugin_id))
    }

    fn read_nested_objects(&self, plugin_id: &str, parent_id: &str) -> Result<Vec<RawEntity>> {
        debug!(
            plugin_id = plugin_id,
            parent_id = parent_id,
            "Reading nested plugin objects"
        );
        self.block_on(self.read_nested_objects_async(plugin_id, parent_id))
    }

    fn handle_lifecycle(&self, plugin_id: &str, event: PluginLifecycleEvent) {
        info!(
            plugin_id = plugin_id,
            event = ?event,
            "Plugin lifecycle event"
        );
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use simd_json::json;

    #[test]
    fn should_project_nested_plugin_objects() {
        let state = json!({
            "interfaces": [
                {
                    "name": "wg0",
                    "peers": [
                        { "name": "peer-a" }
                    ]
                }
            ],
            "metadata": {
                "enabled": true
            }
        });

        let entities = SystemPluginReader::collect_nested_entities("wireguard", &state, "plugin");
        let entity_ids = entities
            .iter()
            .map(|entity| entity.entity_id.clone())
            .collect::<Vec<_>>();

        assert!(entity_ids.contains(&"wireguard:/interfaces".to_string()));
        assert!(entity_ids.contains(&"wireguard:/interfaces/0".to_string()));
        assert!(entity_ids.contains(&"wireguard:/interfaces/0/peers".to_string()));
        assert!(entity_ids.contains(&"wireguard:/metadata".to_string()));

        let peers = entities
            .iter()
            .find(|entity| entity.entity_id == "wireguard:/interfaces/0/peers")
            .expect("peers projection");
        assert_eq!(peers.data["parent_id"], "wireguard:/interfaces/0");
        assert_eq!(peers.data["plugin_id"], "wireguard");
    }

    #[test]
    fn should_consume_canonical_plugin_schema_directly() {
        // The plugin is the schema: projection uses the canonical PluginSchema
        // with no conversion. Fields are keyed in a HashMap.
        let schema = PluginSchema::builder("net")
            .version("1.2.3")
            .category("network")
            .description("Network schema")
            .field(
                "interfaces",
                FieldSchema {
                    field_type: FieldType::Array(Box::new(FieldType::String)),
                    required: true,
                    description: "Interface names".to_string(),
                    default: None,
                    example: None,
                    constraints: Vec::new(),
                    read_only: true,
                    read_only_when: None,
                },
            )
            .build();

        assert_eq!(schema.name, "net");
        assert_eq!(schema.version, "1.2.3");
        assert_eq!(schema.fields.len(), 1);
        let interfaces = schema.fields.get("interfaces").expect("interfaces field");
        assert_eq!(
            interfaces.field_type,
            FieldType::Array(Box::new(FieldType::String))
        );
        assert!(interfaces.read_only);
    }
}

//! Zeroclaw route surface plugin.
//!
//! Publishes the Antigravity-facing model and CLI routing contract through
//! `PluginSchema` so the UI can render provider/model controls from D-Bus.

use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::PluginSchema;
use serde::{Deserialize, Serialize};
use simd_json::{json, OwnedValue as Value};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ZeroclawState {
    pub status: String,
    pub selected_provider: String,
    pub selected_model: String,
    pub transport: Value,
    pub providers: Value,
    pub router: Value,
    pub model_routes: Value,
    pub tools: Value,
    pub config_schema: Value,
    pub ui_surfaces: Value,
    pub structured_output: Value,
}

pub struct ZeroclawPlugin;

impl Default for ZeroclawPlugin {
    fn default() -> Self {
        Self
    }
}

impl ZeroclawPlugin {
    pub fn new() -> Self {
        Self
    }

    fn env_or(key: &str, fallback: &str) -> String {
        std::env::var(key).unwrap_or_else(|_| fallback.to_string())
    }

    pub(crate) fn current_state() -> ZeroclawState {
        // Decoupled from factory: local routing defaults to the on-box gemma4
        // via ollama. gemma4 is also the universal router (see `router` below).
        let selected_provider = Self::env_or("LLM_PROVIDER", "ollama");
        let selected_model = Self::env_or("LLM_MODEL", "gemma4");
        let router_endpoint = Self::env_or("ZEROCLAW_ROUTER_ENDPOINT", "http://localhost:11434");
        let wg_xray_target = Self::env_or("ZEROCLAW_WG_XRAY_TARGET", "wg-xray");
        let grpc_target = Self::env_or("ZEROCLAW_GRPC_TARGET", "http://10.200.0.1:50051");

        ZeroclawState {
            status: "declared".to_string(),
            selected_provider,
            selected_model,
            transport: json!({
                "dbus_object": "/opdbus/v1/plugins/zeroclaw",
                "grpc_target": grpc_target,
                "incus_container": wg_xray_target,
                "browser_surface": "gRPC-Web through op-web",
                "rest_aliases": ["/api/zeroclaw/chat", "/api/llm/chat"],
                // Canonical OSCAL/subid mapping authority — referenced, never copied.
                "policy_source": "/opdbus/v1/plugins/oscal_subid_registry",
            }),
            providers: json!([
                {"id": "factory", "route": "factory", "kind": "orchestrator", "aliases": ["default", "auto"]},
                {"id": "codex", "route": "openai-codex", "kind": "provider", "aliases": ["openai_codex", "codex"]},
                {"id": "ollama", "route": "ollama", "kind": "local", "aliases": ["gemma", "gemma4"]},
                {"id": "antigravity", "route": "antigravity", "kind": "orchestrator", "aliases": ["google.antigravity"]},
                {"id": "google", "route": "gemini", "kind": "provider", "aliases": ["gemini", "google-gemini"]},
                {"id": "opencode", "route": "custom:opencode", "kind": "cli", "aliases": []},
                {"id": "kilocode", "route": "custom:kilocode", "kind": "cli", "aliases": ["kilo-code", "kilo_code"]},
                {"id": "openrouter", "route": "openrouter", "kind": "router", "aliases": []},
                {"id": "anthropic", "route": "anthropic", "kind": "provider", "aliases": []},
                {"id": "openai", "route": "openai", "kind": "provider", "aliases": []},
                {"id": "gemini-cli", "route": "gemini-cli", "kind": "cli", "aliases": []},
                // OSCAL compliance routing: a policy-kind provider (assess, not chat).
                // `source` points at the canonical subid registry — the mapping
                // authority — instead of restating control mappings here.
                {"id": "oscal", "route": "oscal", "kind": "policy", "aliases": ["compliance", "subid", "nist"], "source": "/opdbus/v1/plugins/oscal_subid_registry"}
            ]),
            // gemma4 is the universal router: it classifies EVERY request into a
            // route/tag (provider+model, hint, candidate OSCAL subids). It only
            // emits tags — the deterministic layer (routes below, oscal registry,
            // xray) enforces them. Not just compliance routing.
            router: json!({
                "provider": "ollama",
                "model": "gemma4",
                "endpoint": router_endpoint,
                "scope": "all",
                "role": "context_aware_allocator",
                "emits": ["provider", "model", "hint", "candidate_subids", "confidence", "thinking_budget", "reasoning_effort"],
            }),
            model_routes: json!([
                {
                    "hint": "code",
                    "provider": "openrouter",
                    "upstream_provider": "openrouter",
                    "transport": "direct",
                    "model": "anthropic/claude-sonnet-4.6",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Declared route; backend availability must be projected before execution.",
                    "api_key": null
                },
                {
                    "hint": "fast",
                    "provider": "gemini",
                    "upstream_provider": "gemini",
                    "transport": "direct",
                    "model": "gemini-2.5-flash",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Declared route; backend availability must be projected before execution.",
                    "api_key": null
                },
                {
                    "hint": "local",
                    "provider": "ollama",
                    "upstream_provider": "ollama",
                    "transport": "loopback",
                    "model": "gemma4",
                    "kind": "router",
                    "status": "declared",
                    "available": false,
                    "status_reason": "gemma4 is the declared local classifier; unavailable until Ollama projects it.",
                    "api_key": null
                },
                // Factory auto-routing: selects best available provider based on query type
                {
                    "hint": "auto",
                    "provider": "factory",
                    "upstream_provider": "factory",
                    "transport": "auto",
                    "model": "auto",
                    "kind": "orchestrator",
                    "status": "declared",
                    "available": true,
                    "status_reason": "Factory auto-router available - selects best provider based on query classification.",
                    "api_key": null
                },
                {
                    "hint": "code",
                    "provider": "factory",
                    "upstream_provider": "openrouter",
                    "transport": "direct",
                    "model": "anthropic/claude-sonnet-4.6",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Factory code route -> openrouter/claude; requires backend projection.",
                    "api_key": null
                },
                {
                    "hint": "fast",
                    "provider": "factory",
                    "upstream_provider": "gemini",
                    "transport": "direct",
                    "model": "gemini-2.5-flash",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Factory fast route -> gemini/flash; requires backend projection.",
                    "api_key": null
                },
                {
                    "hint": "local",
                    "provider": "factory",
                    "upstream_provider": "ollama",
                    "transport": "loopback",
                    "model": "gemma4",
                    "kind": "router",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Factory local route -> ollama/gemma4; requires backend projection.",
                    "api_key": null
                },
                {
                    "hint": "reasoning",
                    "provider": "factory",
                    "upstream_provider": "antigravity",
                    "transport": "direct",
                    "model": "gemini-3-pro-preview",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Factory reasoning route; Gemma dynamically allocates thinking budget.",
                    "api_key": null
                },
                // Compliance baseline routed through the OSCAL policy provider; the
                // model id is a canonical OSCAL profile reference resolved via the
                // subid registry, not an LLM model.
                {
                    "hint": "compliance",
                    "provider": "oscal",
                    "upstream_provider": "oscal",
                    "transport": "dbus",
                    "model": "NIST_SP_800-53_Rev5",
                    "kind": "policy",
                    "status": "declared",
                    "available": false,
                    "status_reason": "OSCAL policy provider is declared; unavailable until oscal_subid_registry is projected.",
                    "source": "/opdbus/v1/plugins/oscal_subid_registry",
                    "api_key": null
                }
            ]),
            tools: json!([
                {
                    "name": "zeroclaw.chat",
                    "description": "Send an Antigravity/Zeroclaw chat turn and return structured JSON when response_schema is present.",
                    "parameters": {
                        "type": "object",
                        "properties": {
                            "message": {"type": "string"},
                            "provider": {"type": "string"},
                            "model": {"type": "string"},
                            "response_schema": {"type": "object"}
                        },
                        "required": ["message"]
                    }
                },
                {
                    "name": "zeroclaw.models.list",
                    "description": "List cached or live models for a Zeroclaw provider.",
                    "parameters": {
                        "type": "object",
                        "properties": {"provider": {"type": "string"}},
                        "required": []
                    }
                }
            ]),
            config_schema: json!({
                "source": "zeroclaw config schema",
                "schema_crate": "schemars",
